 201. Bitwise AND of Numbers Range 中文文档
Description Given two integers left and right that represent the range [left, right], return the bitwise AND of all numbers in this range, inclusive.
&nbsp;
Example 1:
Input: left = 5, right = 7 Output: 4 Example 2:
Input: left = 0, right = 0 Output: 0 Example 3:
Input: left = 1, right = 2147483647 Output: 0 &nbsp;
Constraints:
0 &lt;= left &lt;= right &lt;= 231 - 1 Solutions Solution 1 Python3 class Solution: def rangeBitwiseAnd(self, left: int, right: int) -&gt; int: while left &lt; right: right &amp;= right - 1 return right Java class Solution { public int rangeBitwiseAnd(int left, int right) { while (left &lt; right) { right &amp;= (right - 1); } return right; } } C++ class Solution { public: int rangeBitwiseAnd(int left, int right) { while (left &lt; right) { right &amp;= (right - 1); } return right; } }; Go func rangeBitwiseAnd(left int, right int) int { for left &lt; right { right &amp;= (right - 1) } return right } JavaScript /** * @param {number} left * @param {number} right * @return {number} */ var rangeBitwiseAnd = function (left, right) { while (left &lt; right) { right &amp;= right - 1; } return right; }; C# public class Solution { public int RangeBitwiseAnd(int left, int right) { while (left &lt; right) { right &amp;= (right - 1); } return right; } }

 202. Happy Number 中文文档
Description Write an algorithm to determine if a number n is happy.
A happy number is a number defined by the following process:
Starting with any positive integer, replace the number by the sum of the squares of its digits. Repeat the process until the number equals 1 (where it will stay), or it loops endlessly in a cycle which does not include 1. Those numbers for which this process ends in 1 are happy. Return true if n is a happy number, and false if not.
&nbsp;
Example 1:
Input: n = 19 Output: true Explanation: 12 + 92 = 82 82 + 22 = 68 62 + 82 = 100 12 + 02 + 02 = 1 Example 2:
Input: n = 2 Output: false &nbsp;
Constraints:
1 &lt;= n &lt;= 231 - 1 Solutions Solution 1 Python3 class Solution: def isHappy(self, n: int) -&gt; bool: vis = set() while n != 1 and n not in vis: vis.add(n) x = 0 while n: n, v = divmod(n, 10) x += v * v n = x return n == 1 Java class Solution { public boolean isHappy(int n) { Set&lt;Integer&gt; vis = new HashSet&lt;&gt;(); while (n != 1 &amp;&amp; !vis.contains(n)) { vis.add(n); int x = 0; while (n != 0) { x += (n % 10) * (n % 10); n /= 10; } n = x; } return n == 1; } } C++ class Solution { public: bool isHappy(int n) { unordered_set&lt;int&gt; vis; while (n != 1 &amp;&amp; !vis.count(n)) { vis.insert(n); int x = 0; for (; n; n /= 10) { x += (n % 10) * (n % 10); } n = x; } return n == 1; } }; Go func isHappy(n int) bool { vis := map[int]bool{} for n != 1 &amp;&amp; !vis[n] { vis[n] = true x := 0 for ; n &gt; 0; n /= 10 { x += (n % 10) * (n % 10) } n = x } return n == 1 } TypeScript function isHappy(n: number): boolean { const getNext = (n: number) =&gt; { let res = 0; while (n !== 0) { res += (n % 10) ** 2; n = Math.floor(n / 10); } return res; }; const set = new Set(); while (n !== 1) { const next = getNext(n); if (set.has(next)) { return false; } set.add(next); n = next; } return true; } Rust use std::collections::HashSet; impl Solution { fn get_next(mut n: i32) -&gt; i32 { let mut res = 0; while n != 0 { res += (n % 10).pow(2); n /= 10; } res } pub fn is_happy(mut n: i32) -&gt; bool { let mut set = HashSet::new(); while n != 1 { let next = Self::get_next(n); if set.contains(&amp;next) { return false; } set.insert(next); n = next; } true } } C int getNext(int n) { int res = 0; while (n) { res += (n % 10) * (n % 10); n /= 10; } return res; } bool isHappy(int n) { int slow = n; int fast = getNext(n); while (slow != fast) { slow = getNext(slow); fast = getNext(getNext(fast)); } return fast == 1; } Solution 2 Python3 class Solution: def isHappy(self, n: int) -&gt; bool: def next(x): y = 0 while x: x, v = divmod(x, 10) y += v * v return y slow, fast = n, next(n) while slow != fast: slow, fast = next(slow), next(next(fast)) return slow == 1 Java class Solution { public boolean isHappy(int n) { int slow = n, fast = next(n); while (slow != fast) { slow = next(slow); fast = next(next(fast)); } return slow == 1; } private int next(int x) { int y = 0; for (; x &gt; 0; x /= 10) { y += (x % 10) * (x % 10); } return y; } } C++ class Solution { public: bool isHappy(int n) { auto next = [](int x) { int y = 0; for (; x; x /= 10) { y += pow(x % 10, 2); } return y; }; int slow = n, fast = next(n); while (slow != fast) { slow = next(slow); fast = next(next(fast)); } return slow == 1; } }; Go func isHappy(n int) bool { next := func(x int) (y int) { for ; x &gt; 0; x /= 10 { y += (x % 10) * (x % 10) } return } slow, fast := n, next(n) for slow != fast { slow = next(slow) fast = next(next(fast)) } return slow == 1 } TypeScript function isHappy(n: number): boolean { const getNext = (n: number) =&gt; { let res = 0; while (n !== 0) { res += (n % 10) ** 2; n = Math.floor(n / 10); } return res; }; let slow = n; let fast = getNext(n); while (slow !== fast) { slow = getNext(slow); fast = getNext(getNext(fast)); } return fast === 1; } Rust impl Solution { pub fn is_happy(n: i32) -&gt; bool { let get_next = |mut n: i32| { let mut res = 0; while n != 0 { res += (n % 10).pow(2); n /= 10; } res }; let mut slow = n; let mut fast = get_next(n); while slow != fast { slow = get_next(slow); fast = get_next(get_next(fast)); } slow == 1 } }

 203. Remove Linked List Elements 中文文档
Description Given the head of a linked list and an integer val, remove all the nodes of the linked list that has Node.val == val, and return the new head.
&nbsp;
Example 1:
Input: head = [1,2,6,3,4,5,6], val = 6 Output: [1,2,3,4,5] Example 2:
Input: head = [], val = 1 Output: [] Example 3:
Input: head = [7,7,7,7], val = 7 Output: [] &nbsp;
Constraints:
The number of nodes in the list is in the range [0, 104]. 1 &lt;= Node.val &lt;= 50 0 &lt;= val &lt;= 50 Solutions Solution 1 Python3 # Definition for singly-linked list. # class ListNode: # def __init__(self, val=0, next=None): # self.val = val # self.next = next class Solution: def removeElements(self, head: ListNode, val: int) -&gt; ListNode: dummy = ListNode(-1, head) pre = dummy while pre.next: if pre.next.val != val: pre = pre.next else: pre.next = pre.next.next return dummy.next Java /** * Definition for singly-linked list. * public class ListNode { * int val; * ListNode next; * ListNode() {} * ListNode(int val) { this.val = val; } * ListNode(int val, ListNode next) { this.val = val; this.next = next; } * } */ class Solution { public ListNode removeElements(ListNode head, int val) { ListNode dummy = new ListNode(-1, head); ListNode pre = dummy; while (pre.next != null) { if (pre.next.val != val) pre = pre.next; else pre.next = pre.next.next; } return dummy.next; } } C++ class Solution { public: ListNode* removeElements(ListNode* head, int val) { ListNode* dummy = new ListNode(); dummy-&gt;next = head; ListNode* p = dummy; while (p-&gt;next) { if (p-&gt;next-&gt;val == val) { p-&gt;next = p-&gt;next-&gt;next; } else { p = p-&gt;next; } } return dummy-&gt;next; } }; Go func removeElements(head *ListNode, val int) *ListNode { dummy := new(ListNode) dummy.Next = head p := dummy for p.Next != nil { if p.Next.Val == val { p.Next = p.Next.Next } else { p = p.Next } } return dummy.Next } TypeScript /** * Definition for singly-linked list. * class ListNode { * val: number * next: ListNode | null * constructor(val?: number, next?: ListNode | null) { * this.val = (val===undefined ? 0 : val) * this.next = (next===undefined ? null : next) * } * } */ function removeElements(head: ListNode | null, val: number): ListNode | null { const dummy: ListNode = new ListNode(0, head); let cur: ListNode = dummy; while (cur.next != null) { if (cur.next.val === val) { cur.next = cur.next.next; } else { cur = cur.next; } } return dummy.next; } Rust // Definition for singly-linked list. // #[derive(PartialEq, Eq, Clone, Debug)] // pub struct ListNode { // pub val: i32, // pub next: Option&lt;Box&lt;ListNode&gt;&gt; // } // // impl ListNode { // #[inline] // fn new(val: i32) -&gt; Self { // ListNode { // next: None, // val // } // } // } impl Solution { pub fn remove_elements(head: Option&lt;Box&lt;ListNode&gt;&gt;, val: i32) -&gt; Option&lt;Box&lt;ListNode&gt;&gt; { let mut dummy = Box::new(ListNode { val: 0, next: head }); let mut cur = &amp;mut dummy; while let Some(mut node) = cur.next.take() { if node.val == val { cur.next = node.next.take(); } else { cur.next = Some(node); cur = cur.next.as_mut().unwrap(); } } dummy.next.take() } } C# public class Solution { public ListNode RemoveElements(ListNode head, int val) { ListNode newHead = null; ListNode newTail = null; var current = head; while (current != null) { if (current.val != val) { if (newHead == null) { newHead = newTail = current; } else { newTail.next = current; newTail = current; } } current = current.next; } if (newTail != null) newTail.next = null; return newHead; } }

 204. Count Primes 中文文档
Description Given an integer n, return the number of prime numbers that are strictly less than n.
&nbsp;
Example 1:
Input: n = 10 Output: 4 Explanation: There are 4 prime numbers less than 10, they are 2, 3, 5, 7. Example 2:
Input: n = 0 Output: 0 Example 3:
Input: n = 1 Output: 0 &nbsp;
Constraints:
0 &lt;= n &lt;= 5 * 106 Solutions Solution 1 Python3 class Solution: def countPrimes(self, n: int) -&gt; int: primes = [True] * n ans = 0 for i in range(2, n): if primes[i]: ans += 1 for j in range(i + i, n, i): primes[j] = False return ans Java class Solution { public int countPrimes(int n) { boolean[] primes = new boolean[n]; Arrays.fill(primes, true); int ans = 0; for (int i = 2; i &lt; n; ++i) { if (primes[i]) { ++ans; for (int j = i + i; j &lt; n; j += i) { primes[j] = false; } } } return ans; } } C++ class Solution { public: int countPrimes(int n) { vector&lt;bool&gt; primes(n, true); int ans = 0; for (int i = 2; i &lt; n; ++i) { if (primes[i]) { ++ans; for (int j = i; j &lt; n; j += i) primes[j] = false; } } return ans; } }; Go func countPrimes(n int) int { primes := make([]bool, n) for i := range primes { primes[i] = true } ans := 0 for i := 2; i &lt; n; i++ { if primes[i] { ans++ for j := i + i; j &lt; n; j += i { primes[j] = false } } } return ans } JavaScript /** * @param {number} n * @return {number} */ var countPrimes = function (n) { let primes = new Array(n).fill(true); let ans = 0; for (let i = 2; i &lt; n; ++i) { if (primes[i]) { ++ans; for (let j = i + i; j &lt; n; j += i) { primes[j] = false; } } } return ans; }; C# public class Solution { public int CountPrimes(int n) { var notPrimes = new bool[n]; int ans = 0; for (int i = 2; i &lt; n; ++i) { if (!notPrimes[i]) { ++ans; for (int j = i + i; j &lt; n; j += i) { notPrimes[j] = true; } } } return ans; } }

 210. Course Schedule II 中文文档
Description There are a total of numCourses courses you have to take, labeled from 0 to numCourses - 1. You are given an array prerequisites where prerequisites[i] = [ai, bi] indicates that you must take course bi first if you want to take course ai.
For example, the pair [0, 1], indicates that to take course 0 you have to first take course 1. Return the ordering of courses you should take to finish all courses. If there are many valid answers, return any of them. If it is impossible to finish all courses, return an empty array.
&nbsp;
Example 1:
Input: numCourses = 2, prerequisites = [[1,0]] Output: [0,1] Explanation: There are a total of 2 courses to take. To take course 1 you should have finished course 0. So the correct course order is [0,1]. Example 2:
Input: numCourses = 4, prerequisites = [[1,0],[2,0],[3,1],[3,2]] Output: [0,2,1,3] Explanation: There are a total of 4 courses to take. To take course 3 you should have finished both courses 1 and 2. Both courses 1 and 2 should be taken after you finished course 0. So one correct course order is [0,1,2,3]. Another correct ordering is [0,2,1,3]. Example 3:
Input: numCourses = 1, prerequisites = [] Output: [0] &nbsp;
Constraints:
1 &lt;= numCourses &lt;= 2000 0 &lt;= prerequisites.length &lt;= numCourses * (numCourses - 1) prerequisites[i].length == 2 0 &lt;= ai, bi &lt; numCourses ai != bi All the pairs [ai, bi] are distinct. Solutions Solution 1 Python3 class Solution: def findOrder(self, numCourses: int, prerequisites: List[List[int]]) -&gt; List[int]: g = defaultdict(list) indeg = [0] * numCourses for a, b in prerequisites: g[b].append(a) indeg[a] += 1 ans = [] q = deque(i for i, x in enumerate(indeg) if x == 0) while q: i = q.popleft() ans.append(i) for j in g[i]: indeg[j] -= 1 if indeg[j] == 0: q.append(j) return ans if len(ans) == numCourses else [] Java class Solution { public int[] findOrder(int numCourses, int[][] prerequisites) { List&lt;Integer&gt;[] g = new List[numCourses]; Arrays.setAll(g, k -&gt; new ArrayList&lt;&gt;()); int[] indeg = new int[numCourses]; for (var p : prerequisites) { int a = p[0], b = p[1]; g[b].add(a); ++indeg[a]; } Deque&lt;Integer&gt; q = new ArrayDeque&lt;&gt;(); for (int i = 0; i &lt; numCourses; ++i) { if (indeg[i] == 0) { q.offer(i); } } int[] ans = new int[numCourses]; int cnt = 0; while (!q.isEmpty()) { int i = q.poll(); ans[cnt++] = i; for (int j : g[i]) { if (--indeg[j] == 0) { q.offer(j); } } } return cnt == numCourses ? ans : new int[0]; } } C++ class Solution { public: vector&lt;int&gt; findOrder(int numCourses, vector&lt;vector&lt;int&gt;&gt;&amp; prerequisites) { vector&lt;vector&lt;int&gt;&gt; g(numCourses); vector&lt;int&gt; indeg(numCourses); for (auto&amp; p : prerequisites) { int a = p[0], b = p[1]; g[b].push_back(a); ++indeg[a]; } queue&lt;int&gt; q; for (int i = 0; i &lt; numCourses; ++i) { if (indeg[i] == 0) { q.push(i); } } vector&lt;int&gt; ans; while (!q.empty()) { int i = q.front(); q.pop(); ans.push_back(i); for (int j : g[i]) { if (--indeg[j] == 0) { q.push(j); } } } return ans.size() == numCourses ? ans : vector&lt;int&gt;(); } }; Go func findOrder(numCourses int, prerequisites [][]int) []int { g := make([][]int, numCourses) indeg := make([]int, numCourses) for _, p := range prerequisites { a, b := p[0], p[1] g[b] = append(g[b], a) indeg[a]++ } q := []int{} for i, x := range indeg { if x == 0 { q = append(q, i) } } ans := []int{} for len(q) &gt; 0 { i := q[0] q = q[1:] ans = append(ans, i) for _, j := range g[i] { indeg[j]-- if indeg[j] == 0 { q = append(q, j) } } } if len(ans) == numCourses { return ans } return []int{} } TypeScript function findOrder(numCourses: number, prerequisites: number[][]): number[] { const g: number[][] = Array.from({ length: numCourses }, () =&gt; []); const indeg: number[] = new Array(numCourses).fill(0); for (const [a, b] of prerequisites) { g[b].push(a); indeg[a]++; } const q: number[] = []; for (let i = 0; i &lt; numCourses; ++i) { if (indeg[i] === 0) { q.push(i); } } const ans: number[] = []; while (q.length) { const i = q.shift()!; ans.push(i); for (const j of g[i]) { if (--indeg[j] === 0) { q.push(j); } } } return ans.length === numCourses ? ans : []; } Rust impl Solution { pub fn find_order(num_courses: i32, prerequisites: Vec&lt;Vec&lt;i32&gt;&gt;) -&gt; Vec&lt;i32&gt; { let n = num_courses as usize; let mut adjacency = vec![vec![]; n]; let mut entry = vec![0; n]; // init for iter in prerequisites.iter() { let (a, b) = (iter[0], iter[1]); adjacency[b as usize].push(a); entry[a as usize] += 1; } // construct deque &amp; reslut let mut deque = std::collections::VecDeque::new(); for index in 0..n { if entry[index] == 0 { deque.push_back(index); } } let mut result = vec![]; // bfs while !deque.is_empty() { let head = deque.pop_front().unwrap(); result.push(head as i32); // update degree of entry for &amp;out_entry in adjacency[head].iter() { entry[out_entry as usize] -= 1; if entry[out_entry as usize] == 0 { deque.push_back(out_entry as usize); } } } if result.len() == n { result } else { vec![] } } } C# public class Solution { public int[] FindOrder(int numCourses, int[][] prerequisites) { var g = new List&lt;int&gt;[numCourses]; for (int i = 0; i &lt; numCourses; ++i) { g[i] = new List&lt;int&gt;(); } var indeg = new int[numCourses]; foreach (var p in prerequisites) { int a = p[0], b = p[1]; g[b].Add(a); ++indeg[a]; } var q = new Queue&lt;int&gt;(); for (int i = 0; i &lt; numCourses; ++i) { if (indeg[i] == 0) { q.Enqueue(i); } } var ans = new int[numCourses]; var cnt = 0; while (q.Count &gt; 0) { int i = q.Dequeue(); ans[cnt++] = i; foreach (int j in g[i]) { if (--indeg[j] == 0) { q.Enqueue(j); } } } return cnt == numCourses ? ans : new int[0]; } }

 211. 添加与搜索单词 - 数据结构设计 English Version
题目描述 请你设计一个数据结构，支持 添加新单词 和 查找字符串是否与任何先前添加的字符串匹配 。
实现词典类 WordDictionary ：
WordDictionary() 初始化词典对象 void addWord(word) 将 word 添加到数据结构中，之后可以对它进行匹配 bool search(word) 如果数据结构中存在字符串与&nbsp;word 匹配，则返回 true ；否则，返回&nbsp; false 。word 中可能包含一些 '.' ，每个&nbsp;. 都可以表示任何一个字母。 &nbsp;
示例：
输入： ["WordDictionary","addWord","addWord","addWord","search","search","search","search"] [[],["bad"],["dad"],["mad"],["pad"],["bad"],[".ad"],["b.."]] 输出： [null,null,null,null,false,true,true,true] 解释： WordDictionary wordDictionary = new WordDictionary(); wordDictionary.addWord("bad"); wordDictionary.addWord("dad"); wordDictionary.addWord("mad"); wordDictionary.search("pad"); // 返回 False wordDictionary.search("bad"); // 返回 True wordDictionary.search(".ad"); // 返回 True wordDictionary.search("b.."); // 返回 True &nbsp;
提示：
1 &lt;= word.length &lt;= 25 addWord 中的 word 由小写英文字母组成 search 中的 word 由 '.' 或小写英文字母组成 最多调用 104 次 addWord 和 search 解法 方法一 Python3 class Trie: def __init__(self): self.children = [None] * 26 self.is_end = False class WordDictionary: def __init__(self): self.trie = Trie() def addWord(self, word: str) -&gt; None: node = self.trie for c in word: idx = ord(c) - ord(&#39;a&#39;) if node.children[idx] is None: node.children[idx] = Trie() node = node.children[idx] node.is_end = True def search(self, word: str) -&gt; bool: def search(word, node): for i in range(len(word)): c = word[i] idx = ord(c) - ord(&#39;a&#39;) if c != &#39;.&#39; and node.children[idx] is None: return False if c == &#39;.&#39;: for child in node.children: if child is not None and search(word[i + 1 :], child): return True return False node = node.children[idx] return node.is_end return search(word, self.trie) # Your WordDictionary object will be instantiated and called as such: # obj = WordDictionary() # obj.addWord(word) # param_2 = obj.search(word) Java class Trie { Trie[] children = new Trie[26]; boolean isEnd; } class WordDictionary { private Trie trie; /** Initialize your data structure here. */ public WordDictionary() { trie = new Trie(); } public void addWord(String word) { Trie node = trie; for (char c : word.toCharArray()) { int idx = c - &#39;a&#39;; if (node.children[idx] == null) { node.children[idx] = new Trie(); } node = node.children[idx]; } node.isEnd = true; } public boolean search(String word) { return search(word, trie); } private boolean search(String word, Trie node) { for (int i = 0; i &lt; word.length(); ++i) { char c = word.charAt(i); int idx = c - &#39;a&#39;; if (c != &#39;.&#39; &amp;&amp; node.children[idx] == null) { return false; } if (c == &#39;.&#39;) { for (Trie child : node.children) { if (child != null &amp;&amp; search(word.substring(i + 1), child)) { return true; } } return false; } node = node.children[idx]; } return node.isEnd; } } /** * Your WordDictionary object will be instantiated and called as such: * WordDictionary obj = new WordDictionary(); * obj.addWord(word); * boolean param_2 = obj.search(word); */ C++ class trie { public: vector&lt;trie*&gt; children; bool is_end; trie() { children = vector&lt;trie*&gt;(26, nullptr); is_end = false; } void insert(const string&amp; word) { trie* cur = this; for (char c : word) { c -= &#39;a&#39;; if (cur-&gt;children[c] == nullptr) { cur-&gt;children[c] = new trie; } cur = cur-&gt;children[c]; } cur-&gt;is_end = true; } }; class WordDictionary { private: trie* root; public: WordDictionary() : root(new trie) {} void addWord(string word) { root-&gt;insert(word); } bool search(string word) { return dfs(word, 0, root); } private: bool dfs(const string&amp; word, int i, trie* cur) { if (i == word.size()) { return cur-&gt;is_end; } char c = word[i]; if (c != &#39;.&#39;) { trie* child = cur-&gt;children[c - &#39;a&#39;]; if (child != nullptr &amp;&amp; dfs(word, i + 1, child)) { return true; } } else { for (trie* child : cur-&gt;children) { if (child != nullptr &amp;&amp; dfs(word, i + 1, child)) { return true; } } } return false; } }; /** * Your WordDictionary object will be instantiated and called as such: * WordDictionary* obj = new WordDictionary(); * obj-&gt;addWord(word); * bool param_2 = obj-&gt;search(word); */ Go type WordDictionary struct { root *trie } func Constructor() WordDictionary { return WordDictionary{new(trie)} } func (this *WordDictionary) AddWord(word string) { this.root.insert(word) } func (this *WordDictionary) Search(word string) bool { n := len(word) var dfs func(int, *trie) bool dfs = func(i int, cur *trie) bool { if i == n { return cur.isEnd } c := word[i] if c != &#39;.&#39; { child := cur.children[c-&#39;a&#39;] if child != nil &amp;&amp; dfs(i+1, child) { return true } } else { for _, child := range cur.children { if child != nil &amp;&amp; dfs(i+1, child) { return true } } } return false } return dfs(0, this.root) } type trie struct { children [26]*trie isEnd bool } func (t *trie) insert(word string) { cur := t for _, c := range word { c -= &#39;a&#39; if cur.children[c] == nil { cur.children[c] = new(trie) } cur = cur.children[c] } cur.isEnd = true } /** * Your WordDictionary object will be instantiated and called as such: * obj := Constructor(); * obj.AddWord(word); * param_2 := obj.Search(word); */ C# using System.Collections.Generic; using System.Linq; class TrieNode { public bool IsEnd { get; set; } public TrieNode[] Children { get; set; } public TrieNode() { Children = new TrieNode[26]; } } public class WordDictionary { private TrieNode root; public WordDictionary() { root = new TrieNode(); } public void AddWord(string word) { var node = root; for (var i = 0; i &lt; word.Length; ++i) { TrieNode nextNode; var index = word[i] - &#39;a&#39;; nextNode = node.Children[index]; if (nextNode == null) { nextNode = new TrieNode(); node.Children[index] = nextNode; } node = nextNode; } node.IsEnd = true; } public bool Search(string word) { var queue = new Queue&lt;TrieNode&gt;(); queue.Enqueue(root); for (var i = 0; i &lt; word.Length; ++i) { var count = queue.Count; while (count-- &gt; 0) { var node = queue.Dequeue(); if (word[i] == &#39;.&#39;) { foreach (var nextNode in node.Children) { if (nextNode != null) { queue.Enqueue(nextNode); } } } else { var nextNode = node.Children[word[i] - &#39;a&#39;]; if (nextNode != null) { queue.Enqueue(nextNode); } } } } return queue.Any(n =&gt; n.IsEnd); } }

 211. Design Add and Search Words Data Structure 中文文档
Description Design a data structure that supports adding new words and finding if a string matches any previously added string.
Implement the WordDictionary class:
WordDictionary()&nbsp;Initializes the object. void addWord(word) Adds word to the data structure, it can be matched later. bool search(word)&nbsp;Returns true if there is any string in the data structure that matches word&nbsp;or false otherwise. word may contain dots &#39;.&#39; where dots can be matched with any letter. &nbsp;
Example:
Input [&quot;WordDictionary&quot;,&quot;addWord&quot;,&quot;addWord&quot;,&quot;addWord&quot;,&quot;search&quot;,&quot;search&quot;,&quot;search&quot;,&quot;search&quot;] [[],[&quot;bad&quot;],[&quot;dad&quot;],[&quot;mad&quot;],[&quot;pad&quot;],[&quot;bad&quot;],[&quot;.ad&quot;],[&quot;b..&quot;]] Output [null,null,null,null,false,true,true,true] Explanation WordDictionary wordDictionary = new WordDictionary(); wordDictionary.addWord(&quot;bad&quot;); wordDictionary.addWord(&quot;dad&quot;); wordDictionary.addWord(&quot;mad&quot;); wordDictionary.search(&quot;pad&quot;); // return False wordDictionary.search(&quot;bad&quot;); // return True wordDictionary.search(&quot;.ad&quot;); // return True wordDictionary.search(&quot;b..&quot;); // return True &nbsp;
Constraints:
1 &lt;= word.length &lt;= 25 word in addWord consists of lowercase English letters. word in search consist of &#39;.&#39; or lowercase English letters. There will be at most 2 dots in word for search queries. At most 104 calls will be made to addWord and search. Solutions Solution 1 Python3 class Trie: def __init__(self): self.children = [None] * 26 self.is_end = False class WordDictionary: def __init__(self): self.trie = Trie() def addWord(self, word: str) -&gt; None: node = self.trie for c in word: idx = ord(c) - ord(&#39;a&#39;) if node.children[idx] is None: node.children[idx] = Trie() node = node.children[idx] node.is_end = True def search(self, word: str) -&gt; bool: def search(word, node): for i in range(len(word)): c = word[i] idx = ord(c) - ord(&#39;a&#39;) if c != &#39;.&#39; and node.children[idx] is None: return False if c == &#39;.&#39;: for child in node.children: if child is not None and search(word[i + 1 :], child): return True return False node = node.children[idx] return node.is_end return search(word, self.trie) # Your WordDictionary object will be instantiated and called as such: # obj = WordDictionary() # obj.addWord(word) # param_2 = obj.search(word) Java class Trie { Trie[] children = new Trie[26]; boolean isEnd; } class WordDictionary { private Trie trie; /** Initialize your data structure here. */ public WordDictionary() { trie = new Trie(); } public void addWord(String word) { Trie node = trie; for (char c : word.toCharArray()) { int idx = c - &#39;a&#39;; if (node.children[idx] == null) { node.children[idx] = new Trie(); } node = node.children[idx]; } node.isEnd = true; } public boolean search(String word) { return search(word, trie); } private boolean search(String word, Trie node) { for (int i = 0; i &lt; word.length(); ++i) { char c = word.charAt(i); int idx = c - &#39;a&#39;; if (c != &#39;.&#39; &amp;&amp; node.children[idx] == null) { return false; } if (c == &#39;.&#39;) { for (Trie child : node.children) { if (child != null &amp;&amp; search(word.substring(i + 1), child)) { return true; } } return false; } node = node.children[idx]; } return node.isEnd; } } /** * Your WordDictionary object will be instantiated and called as such: * WordDictionary obj = new WordDictionary(); * obj.addWord(word); * boolean param_2 = obj.search(word); */ C++ class trie { public: vector&lt;trie*&gt; children; bool is_end; trie() { children = vector&lt;trie*&gt;(26, nullptr); is_end = false; } void insert(const string&amp; word) { trie* cur = this; for (char c : word) { c -= &#39;a&#39;; if (cur-&gt;children[c] == nullptr) { cur-&gt;children[c] = new trie; } cur = cur-&gt;children[c]; } cur-&gt;is_end = true; } }; class WordDictionary { private: trie* root; public: WordDictionary() : root(new trie) {} void addWord(string word) { root-&gt;insert(word); } bool search(string word) { return dfs(word, 0, root); } private: bool dfs(const string&amp; word, int i, trie* cur) { if (i == word.size()) { return cur-&gt;is_end; } char c = word[i]; if (c != &#39;.&#39;) { trie* child = cur-&gt;children[c - &#39;a&#39;]; if (child != nullptr &amp;&amp; dfs(word, i + 1, child)) { return true; } } else { for (trie* child : cur-&gt;children) { if (child != nullptr &amp;&amp; dfs(word, i + 1, child)) { return true; } } } return false; } }; /** * Your WordDictionary object will be instantiated and called as such: * WordDictionary* obj = new WordDictionary(); * obj-&gt;addWord(word); * bool param_2 = obj-&gt;search(word); */ Go type WordDictionary struct { root *trie } func Constructor() WordDictionary { return WordDictionary{new(trie)} } func (this *WordDictionary) AddWord(word string) { this.root.insert(word) } func (this *WordDictionary) Search(word string) bool { n := len(word) var dfs func(int, *trie) bool dfs = func(i int, cur *trie) bool { if i == n { return cur.isEnd } c := word[i] if c != &#39;.&#39; { child := cur.children[c-&#39;a&#39;] if child != nil &amp;&amp; dfs(i+1, child) { return true } } else { for _, child := range cur.children { if child != nil &amp;&amp; dfs(i+1, child) { return true } } } return false } return dfs(0, this.root) } type trie struct { children [26]*trie isEnd bool } func (t *trie) insert(word string) { cur := t for _, c := range word { c -= &#39;a&#39; if cur.children[c] == nil { cur.children[c] = new(trie) } cur = cur.children[c] } cur.isEnd = true } /** * Your WordDictionary object will be instantiated and called as such: * obj := Constructor(); * obj.AddWord(word); * param_2 := obj.Search(word); */ C# using System.Collections.Generic; using System.Linq; class TrieNode { public bool IsEnd { get; set; } public TrieNode[] Children { get; set; } public TrieNode() { Children = new TrieNode[26]; } } public class WordDictionary { private TrieNode root; public WordDictionary() { root = new TrieNode(); } public void AddWord(string word) { var node = root; for (var i = 0; i &lt; word.Length; ++i) { TrieNode nextNode; var index = word[i] - &#39;a&#39;; nextNode = node.Children[index]; if (nextNode == null) { nextNode = new TrieNode(); node.Children[index] = nextNode; } node = nextNode; } node.IsEnd = true; } public bool Search(string word) { var queue = new Queue&lt;TrieNode&gt;(); queue.Enqueue(root); for (var i = 0; i &lt; word.Length; ++i) { var count = queue.Count; while (count-- &gt; 0) { var node = queue.Dequeue(); if (word[i] == &#39;.&#39;) { foreach (var nextNode in node.Children) { if (nextNode != null) { queue.Enqueue(nextNode); } } } else { var nextNode = node.Children[word[i] - &#39;a&#39;]; if (nextNode != null) { queue.Enqueue(nextNode); } } } } return queue.Any(n =&gt; n.IsEnd); } }

 212. Word Search II 中文文档
Description Given an m x n board&nbsp;of characters and a list of strings words, return all words on the board.
Each word must be constructed from letters of sequentially adjacent cells, where adjacent cells are horizontally or vertically neighboring. The same letter cell may not be used more than once in a word.
&nbsp;
Example 1:
Input: board = [[&quot;o&quot;,&quot;a&quot;,&quot;a&quot;,&quot;n&quot;],[&quot;e&quot;,&quot;t&quot;,&quot;a&quot;,&quot;e&quot;],[&quot;i&quot;,&quot;h&quot;,&quot;k&quot;,&quot;r&quot;],[&quot;i&quot;,&quot;f&quot;,&quot;l&quot;,&quot;v&quot;]], words = [&quot;oath&quot;,&quot;pea&quot;,&quot;eat&quot;,&quot;rain&quot;] Output: [&quot;eat&quot;,&quot;oath&quot;] Example 2:
Input: board = [[&quot;a&quot;,&quot;b&quot;],[&quot;c&quot;,&quot;d&quot;]], words = [&quot;abcb&quot;] Output: [] &nbsp;
Constraints:
m == board.length n == board[i].length 1 &lt;= m, n &lt;= 12 board[i][j] is a lowercase English letter. 1 &lt;= words.length &lt;= 3 * 104 1 &lt;= words[i].length &lt;= 10 words[i] consists of lowercase English letters. All the strings of words are unique. Solutions Solution 1 Python3 class Trie: def __init__(self): self.children: List[Trie | None] = [None] * 26 self.ref: int = -1 def insert(self, w: str, ref: int): node = self for c in w: idx = ord(c) - ord(&#39;a&#39;) if node.children[idx] is None: node.children[idx] = Trie() node = node.children[idx] node.ref = ref class Solution: def findWords(self, board: List[List[str]], words: List[str]) -&gt; List[str]: def dfs(node: Trie, i: int, j: int): idx = ord(board[i][j]) - ord(&#39;a&#39;) if node.children[idx] is None: return node = node.children[idx] if node.ref &gt;= 0: ans.append(words[node.ref]) node.ref = -1 c = board[i][j] board[i][j] = &#39;#&#39; for a, b in pairwise((-1, 0, 1, 0, -1)): x, y = i + a, j + b if 0 &lt;= x &lt; m and 0 &lt;= y &lt; n and board[x][y] != &#39;#&#39;: dfs(node, x, y) board[i][j] = c tree = Trie() for i, w in enumerate(words): tree.insert(w, i) m, n = len(board), len(board[0]) ans = [] for i in range(m): for j in range(n): dfs(tree, i, j) return ans Java class Trie { Trie[] children = new Trie[26]; int ref = -1; public void insert(String w, int ref) { Trie node = this; for (int i = 0; i &lt; w.length(); ++i) { int j = w.charAt(i) - &#39;a&#39;; if (node.children[j] == null) { node.children[j] = new Trie(); } node = node.children[j]; } node.ref = ref; } } class Solution { private char[][] board; private String[] words; private List&lt;String&gt; ans = new ArrayList&lt;&gt;(); public List&lt;String&gt; findWords(char[][] board, String[] words) { this.board = board; this.words = words; Trie tree = new Trie(); for (int i = 0; i &lt; words.length; ++i) { tree.insert(words[i], i); } int m = board.length, n = board[0].length; for (int i = 0; i &lt; m; ++i) { for (int j = 0; j &lt; n; ++j) { dfs(tree, i, j); } } return ans; } private void dfs(Trie node, int i, int j) { int idx = board[i][j] - &#39;a&#39;; if (node.children[idx] == null) { return; } node = node.children[idx]; if (node.ref != -1) { ans.add(words[node.ref]); node.ref = -1; } char c = board[i][j]; board[i][j] = &#39;#&#39;; int[] dirs = {-1, 0, 1, 0, -1}; for (int k = 0; k &lt; 4; ++k) { int x = i + dirs[k], y = j + dirs[k + 1]; if (x &gt;= 0 &amp;&amp; x &lt; board.length &amp;&amp; y &gt;= 0 &amp;&amp; y &lt; board[0].length &amp;&amp; board[x][y] != &#39;#&#39;) { dfs(node, x, y); } } board[i][j] = c; } } C++ class Trie { public: vector&lt;Trie*&gt; children; int ref; Trie() : children(26, nullptr) , ref(-1) {} void insert(const string&amp; w, int ref) { Trie* node = this; for (char c : w) { c -= &#39;a&#39;; if (!node-&gt;children[c]) { node-&gt;children[c] = new Trie(); } node = node-&gt;children[c]; } node-&gt;ref = ref; } }; class Solution { public: vector&lt;string&gt; findWords(vector&lt;vector&lt;char&gt;&gt;&amp; board, vector&lt;string&gt;&amp; words) { Trie* tree = new Trie(); for (int i = 0; i &lt; words.size(); ++i) { tree-&gt;insert(words[i], i); } vector&lt;string&gt; ans; int m = board.size(), n = board[0].size(); function&lt;void(Trie*, int, int)&gt; dfs = [&amp;](Trie* node, int i, int j) { int idx = board[i][j] - &#39;a&#39;; if (!node-&gt;children[idx]) { return; } node = node-&gt;children[idx]; if (node-&gt;ref != -1) { ans.emplace_back(words[node-&gt;ref]); node-&gt;ref = -1; } int dirs[5] = {-1, 0, 1, 0, -1}; char c = board[i][j]; board[i][j] = &#39;#&#39;; for (int k = 0; k &lt; 4; ++k) { int x = i + dirs[k], y = j + dirs[k + 1]; if (x &gt;= 0 &amp;&amp; x &lt; m &amp;&amp; y &gt;= 0 &amp;&amp; y &lt; n &amp;&amp; board[x][y] != &#39;#&#39;) { dfs(node, x, y); } } board[i][j] = c; }; for (int i = 0; i &lt; m; ++i) { for (int j = 0; j &lt; n; ++j) { dfs(tree, i, j); } } return ans; } }; Go type Trie struct { children [26]*Trie ref int } func newTrie() *Trie { return &amp;Trie{ref: -1} } func (this *Trie) insert(w string, ref int) { node := this for _, c := range w { c -= &#39;a&#39; if node.children[c] == nil { node.children[c] = newTrie() } node = node.children[c] } node.ref = ref } func findWords(board [][]byte, words []string) (ans []string) { trie := newTrie() for i, w := range words { trie.insert(w, i) } m, n := len(board), len(board[0]) var dfs func(*Trie, int, int) dfs = func(node *Trie, i, j int) { idx := board[i][j] - &#39;a&#39; if node.children[idx] == nil { return } node = node.children[idx] if node.ref != -1 { ans = append(ans, words[node.ref]) node.ref = -1 } c := board[i][j] board[i][j] = &#39;#&#39; dirs := [5]int{-1, 0, 1, 0, -1} for k := 0; k &lt; 4; k++ { x, y := i+dirs[k], j+dirs[k+1] if x &gt;= 0 &amp;&amp; x &lt; m &amp;&amp; y &gt;= 0 &amp;&amp; y &lt; n &amp;&amp; board[x][y] != &#39;#&#39; { dfs(node, x, y) } } board[i][j] = c } for i := 0; i &lt; m; i++ { for j := 0; j &lt; n; j++ { dfs(trie, i, j) } } return } TypeScript class Trie { children: Trie[]; ref: number; constructor() { this.children = new Array(26); this.ref = -1; } insert(w: string, ref: number): void { let node: Trie = this; for (let i = 0; i &lt; w.length; i++) { const c = w.charCodeAt(i) - 97; if (node.children[c] == null) { node.children[c] = new Trie(); } node = node.children[c]; } node.ref = ref; } } function findWords(board: string[][], words: string[]): string[] { const tree = new Trie(); for (let i = 0; i &lt; words.length; ++i) { tree.insert(words[i], i); } const m = board.length; const n = board[0].length; const ans: string[] = []; const dirs: number[] = [-1, 0, 1, 0, -1]; const dfs = (node: Trie, i: number, j: number) =&gt; { const idx = board[i][j].charCodeAt(0) - 97; if (node.children[idx] == null) { return; } node = node.children[idx]; if (node.ref != -1) { ans.push(words[node.ref]); node.ref = -1; } const c = board[i][j]; board[i][j] = &#39;#&#39;; for (let k = 0; k &lt; 4; ++k) { const x = i + dirs[k]; const y = j + dirs[k + 1]; if (x &gt;= 0 &amp;&amp; x &lt; m &amp;&amp; y &gt;= 0 &amp;&amp; y &lt; n &amp;&amp; board[x][y] != &#39;#&#39;) { dfs(node, x, y); } } board[i][j] = c; }; for (let i = 0; i &lt; m; ++i) { for (let j = 0; j &lt; n; ++j) { dfs(tree, i, j); } } return ans; }

 225. 用队列实现栈 English Version
题目描述 请你仅使用两个队列实现一个后入先出（LIFO）的栈，并支持普通栈的全部四种操作（push、top、pop 和 empty）。
实现 MyStack 类：
void push(int x) 将元素 x 压入栈顶。 int pop() 移除并返回栈顶元素。 int top() 返回栈顶元素。 boolean empty() 如果栈是空的，返回 true ；否则，返回 false 。 &nbsp;
注意：
你只能使用队列的标准操作 —— 也就是&nbsp;push to back、peek/pop from front、size 和&nbsp;is empty&nbsp;这些操作。 你所使用的语言也许不支持队列。&nbsp;你可以使用 list （列表）或者 deque（双端队列）来模拟一个队列&nbsp;, 只要是标准的队列操作即可。 &nbsp;
示例：
输入： ["MyStack", "push", "push", "top", "pop", "empty"] [[], [1], [2], [], [], []] 输出： [null, null, null, 2, 2, false] 解释： MyStack myStack = new MyStack(); myStack.push(1); myStack.push(2); myStack.top(); // 返回 2 myStack.pop(); // 返回 2 myStack.empty(); // 返回 False &nbsp;
提示：
1 &lt;= x &lt;= 9 最多调用100 次 push、pop、top 和 empty 每次调用 pop 和 top 都保证栈不为空 &nbsp;
进阶：你能否仅用一个队列来实现栈。
解法 方法一：两个队列 我们使用两个队列 $q_1$ 和 $q_2$，其中 $q_1$ 用于存储栈中的元素，而 $q_2$ 用于辅助实现栈的操作。
push 操作：将元素压入 $q_2$，然后将 $q_1$ 中的元素依次弹出并压入 $q_2$，最后交换 $q_1$ 和 $q_2$ 的引用。时间复杂度 $O(n)$。 pop 操作：直接弹出 $q_1$ 的队首元素。时间复杂度 $O(1)$。 top 操作：直接返回 $q_1$ 的队首元素。时间复杂度 $O(1)$。 empty 操作：判断 $q_1$ 是否为空。时间复杂度 $O(1)$。 空间复杂度 $O(n)$，其中 $n$ 是栈中元素的个数。
Python3 class MyStack: def __init__(self): self.q1 = deque() self.q2 = deque() def push(self, x: int) -&gt; None: self.q2.append(x) while self.q1: self.q2.append(self.q1.popleft()) self.q1, self.q2 = self.q2, self.q1 def pop(self) -&gt; int: return self.q1.popleft() def top(self) -&gt; int: return self.q1[0] def empty(self) -&gt; bool: return len(self.q1) == 0 # Your MyStack object will be instantiated and called as such: # obj = MyStack() # obj.push(x) # param_2 = obj.pop() # param_3 = obj.top() # param_4 = obj.empty() Java class MyStack { private Deque&lt;Integer&gt; q1 = new ArrayDeque&lt;&gt;(); private Deque&lt;Integer&gt; q2 = new ArrayDeque&lt;&gt;(); public MyStack() { } public void push(int x) { q2.offer(x); while (!q1.isEmpty()) { q2.offer(q1.poll()); } Deque&lt;Integer&gt; q = q1; q1 = q2; q2 = q; } public int pop() { return q1.poll(); } public int top() { return q1.peek(); } public boolean empty() { return q1.isEmpty(); } } /** * Your MyStack object will be instantiated and called as such: * MyStack obj = new MyStack(); * obj.push(x); * int param_2 = obj.pop(); * int param_3 = obj.top(); * boolean param_4 = obj.empty(); */ C++ class MyStack { public: MyStack() { } void push(int x) { q2.push(x); while (!q1.empty()) { q2.push(q1.front()); q1.pop(); } swap(q1, q2); } int pop() { int x = q1.front(); q1.pop(); return x; } int top() { return q1.front(); } bool empty() { return q1.empty(); } private: queue&lt;int&gt; q1; queue&lt;int&gt; q2; }; /** * Your MyStack object will be instantiated and called as such: * MyStack* obj = new MyStack(); * obj-&gt;push(x); * int param_2 = obj-&gt;pop(); * int param_3 = obj-&gt;top(); * bool param_4 = obj-&gt;empty(); */ Go type MyStack struct { q1 []int q2 []int } func Constructor() MyStack { return MyStack{} } func (this *MyStack) Push(x int) { this.q2 = append(this.q2, x) for len(this.q1) &gt; 0 { this.q2 = append(this.q2, this.q1[0]) this.q1 = this.q1[1:] } this.q1, this.q2 = this.q2, this.q1 } func (this *MyStack) Pop() int { x := this.q1[0] this.q1 = this.q1[1:] return x } func (this *MyStack) Top() int { return this.q1[0] } func (this *MyStack) Empty() bool { return len(this.q1) == 0 } /** * Your MyStack object will be instantiated and called as such: * obj := Constructor(); * obj.Push(x); * param_2 := obj.Pop(); * param_3 := obj.Top(); * param_4 := obj.Empty(); */ TypeScript class MyStack { q1: number[] = []; q2: number[] = []; constructor() {} push(x: number): void { this.q2.push(x); while (this.q1.length) { this.q2.push(this.q1.shift()!); } [this.q1, this.q2] = [this.q2, this.q1]; } pop(): number { return this.q1.shift()!; } top(): number { return this.q1[0]; } empty(): boolean { return this.q1.length === 0; } } /** * Your MyStack object will be instantiated and called as such: * var obj = new MyStack() * obj.push(x) * var param_2 = obj.pop() * var param_3 = obj.top() * var param_4 = obj.empty() */ Rust use std::collections::VecDeque; struct MyStack { /// There could only be two status at all time /// 1. One contains N elements, the other is empty /// 2. One contains N - 1 elements, the other contains exactly 1 element q_1: VecDeque&lt;i32&gt;, q_2: VecDeque&lt;i32&gt;, // Either 1 or 2, originally begins from 1 index: i32, } impl MyStack { fn new() -&gt; Self { Self { q_1: VecDeque::new(), q_2: VecDeque::new(), index: 1, } } fn move_data(&amp;mut self) { // Always move from q1 to q2 assert!(self.q_2.len() == 1); while !self.q_1.is_empty() { self.q_2.push_back(self.q_1.pop_front().unwrap()); } let tmp = self.q_1.clone(); self.q_1 = self.q_2.clone(); self.q_2 = tmp; } fn push(&amp;mut self, x: i32) { self.q_2.push_back(x); self.move_data(); } fn pop(&amp;mut self) -&gt; i32 { self.q_1.pop_front().unwrap() } fn top(&amp;mut self) -&gt; i32 { *self.q_1.front().unwrap() } fn empty(&amp;self) -&gt; bool { self.q_1.is_empty() } }

 225. Implement Stack using Queues 中文文档
Description Implement a last-in-first-out (LIFO) stack using only two queues. The implemented stack should support all the functions of a normal stack (push, top, pop, and empty).
Implement the MyStack class:
void push(int x) Pushes element x to the top of the stack. int pop() Removes the element on the top of the stack and returns it. int top() Returns the element on the top of the stack. boolean empty() Returns true if the stack is empty, false otherwise. Notes:
You must use only standard operations of a queue, which means that only push to back, peek/pop from front, size and is empty operations are valid. Depending on your language, the queue may not be supported natively. You may simulate a queue using a list or deque (double-ended queue) as long as you use only a queue&#39;s standard operations. &nbsp;
Example 1:
Input [&quot;MyStack&quot;, &quot;push&quot;, &quot;push&quot;, &quot;top&quot;, &quot;pop&quot;, &quot;empty&quot;] [[], [1], [2], [], [], []] Output [null, null, null, 2, 2, false] Explanation MyStack myStack = new MyStack(); myStack.push(1); myStack.push(2); myStack.top(); // return 2 myStack.pop(); // return 2 myStack.empty(); // return False &nbsp;
Constraints:
1 &lt;= x &lt;= 9 At most 100 calls will be made to push, pop, top, and empty. All the calls to pop and top are valid. &nbsp;
Follow-up: Can you implement the stack using only one queue?
Solutions Solution 1: Two Queues We use two queues $q_1$ and $q_2$, where $q_1$ is used to store the elements in the stack, and $q_2$ is used to assist in implementing the stack operations.
push operation: Push the element into $q_2$, then pop the elements in $q_1$ one by one and push them into $q_2$, finally swap the references of $q_1$ and $q_2$. The time complexity is $O(n)$. pop operation: Directly pop the front element of $q_1$. The time complexity is $O(1)$. top operation: Directly return the front element of $q_1$. The time complexity is $O(1)$. empty operation: Check whether $q_1$ is empty. The time complexity is $O(1)$. The space complexity is $O(n)$, where $n$ is the number of elements in the stack.
Python3 class MyStack: def __init__(self): self.q1 = deque() self.q2 = deque() def push(self, x: int) -&gt; None: self.q2.append(x) while self.q1: self.q2.append(self.q1.popleft()) self.q1, self.q2 = self.q2, self.q1 def pop(self) -&gt; int: return self.q1.popleft() def top(self) -&gt; int: return self.q1[0] def empty(self) -&gt; bool: return len(self.q1) == 0 # Your MyStack object will be instantiated and called as such: # obj = MyStack() # obj.push(x) # param_2 = obj.pop() # param_3 = obj.top() # param_4 = obj.empty() Java class MyStack { private Deque&lt;Integer&gt; q1 = new ArrayDeque&lt;&gt;(); private Deque&lt;Integer&gt; q2 = new ArrayDeque&lt;&gt;(); public MyStack() { } public void push(int x) { q2.offer(x); while (!q1.isEmpty()) { q2.offer(q1.poll()); } Deque&lt;Integer&gt; q = q1; q1 = q2; q2 = q; } public int pop() { return q1.poll(); } public int top() { return q1.peek(); } public boolean empty() { return q1.isEmpty(); } } /** * Your MyStack object will be instantiated and called as such: * MyStack obj = new MyStack(); * obj.push(x); * int param_2 = obj.pop(); * int param_3 = obj.top(); * boolean param_4 = obj.empty(); */ C++ class MyStack { public: MyStack() { } void push(int x) { q2.push(x); while (!q1.empty()) { q2.push(q1.front()); q1.pop(); } swap(q1, q2); } int pop() { int x = q1.front(); q1.pop(); return x; } int top() { return q1.front(); } bool empty() { return q1.empty(); } private: queue&lt;int&gt; q1; queue&lt;int&gt; q2; }; /** * Your MyStack object will be instantiated and called as such: * MyStack* obj = new MyStack(); * obj-&gt;push(x); * int param_2 = obj-&gt;pop(); * int param_3 = obj-&gt;top(); * bool param_4 = obj-&gt;empty(); */ Go type MyStack struct { q1 []int q2 []int } func Constructor() MyStack { return MyStack{} } func (this *MyStack) Push(x int) { this.q2 = append(this.q2, x) for len(this.q1) &gt; 0 { this.q2 = append(this.q2, this.q1[0]) this.q1 = this.q1[1:] } this.q1, this.q2 = this.q2, this.q1 } func (this *MyStack) Pop() int { x := this.q1[0] this.q1 = this.q1[1:] return x } func (this *MyStack) Top() int { return this.q1[0] } func (this *MyStack) Empty() bool { return len(this.q1) == 0 } /** * Your MyStack object will be instantiated and called as such: * obj := Constructor(); * obj.Push(x); * param_2 := obj.Pop(); * param_3 := obj.Top(); * param_4 := obj.Empty(); */ TypeScript class MyStack { q1: number[] = []; q2: number[] = []; constructor() {} push(x: number): void { this.q2.push(x); while (this.q1.length) { this.q2.push(this.q1.shift()!); } [this.q1, this.q2] = [this.q2, this.q1]; } pop(): number { return this.q1.shift()!; } top(): number { return this.q1[0]; } empty(): boolean { return this.q1.length === 0; } } /** * Your MyStack object will be instantiated and called as such: * var obj = new MyStack() * obj.push(x) * var param_2 = obj.pop() * var param_3 = obj.top() * var param_4 = obj.empty() */ Rust use std::collections::VecDeque; struct MyStack { /// There could only be two status at all time /// 1. One contains N elements, the other is empty /// 2. One contains N - 1 elements, the other contains exactly 1 element q_1: VecDeque&lt;i32&gt;, q_2: VecDeque&lt;i32&gt;, // Either 1 or 2, originally begins from 1 index: i32, } impl MyStack { fn new() -&gt; Self { Self { q_1: VecDeque::new(), q_2: VecDeque::new(), index: 1, } } fn move_data(&amp;mut self) { // Always move from q1 to q2 assert!(self.q_2.len() == 1); while !self.q_1.is_empty() { self.q_2.push_back(self.q_1.pop_front().unwrap()); } let tmp = self.q_1.clone(); self.q_1 = self.q_2.clone(); self.q_2 = tmp; } fn push(&amp;mut self, x: i32) { self.q_2.push_back(x); self.move_data(); } fn pop(&amp;mut self) -&gt; i32 { self.q_1.pop_front().unwrap() } fn top(&amp;mut self) -&gt; i32 { *self.q_1.front().unwrap() } fn empty(&amp;self) -&gt; bool { self.q_1.is_empty() } }

 229. 多数元素 II English Version
题目描述 给定一个大小为&nbsp;n&nbsp;的整数数组，找出其中所有出现超过&nbsp;⌊n / 3⌋&nbsp;次的元素。
&nbsp;
