解法 方法一 Python3 class Solution: def majorityElement(self, nums: List[int]) -&gt; List[int]: n1 = n2 = 0 m1, m2 = 0, 1 for m in nums: if m == m1: n1 += 1 elif m == m2: n2 += 1 elif n1 == 0: m1, n1 = m, 1 elif n2 == 0: m2, n2 = m, 1 else: n1, n2 = n1 - 1, n2 - 1 return [m for m in [m1, m2] if nums.count(m) &gt; len(nums) // 3] Java class Solution { public List&lt;Integer&gt; majorityElement(int[] nums) { int n1 = 0, n2 = 0; int m1 = 0, m2 = 1; for (int m : nums) { if (m == m1) { ++n1; } else if (m == m2) { ++n2; } else if (n1 == 0) { m1 = m; ++n1; } else if (n2 == 0) { m2 = m; ++n2; } else { --n1; --n2; } } List&lt;Integer&gt; ans = new ArrayList&lt;&gt;(); n1 = 0; n2 = 0; for (int m : nums) { if (m == m1) { ++n1; } else if (m == m2) { ++n2; } } if (n1 &gt; nums.length / 3) { ans.add(m1); } if (n2 &gt; nums.length / 3) { ans.add(m2); } return ans; } } C++ class Solution { public: vector&lt;int&gt; majorityElement(vector&lt;int&gt;&amp; nums) { int n1 = 0, n2 = 0; int m1 = 0, m2 = 1; for (int m : nums) { if (m == m1) ++n1; else if (m == m2) ++n2; else if (n1 == 0) { m1 = m; ++n1; } else if (n2 == 0) { m2 = m; ++n2; } else { --n1; --n2; } } vector&lt;int&gt; ans; if (count(nums.begin(), nums.end(), m1) &gt; nums.size() / 3) ans.push_back(m1); if (count(nums.begin(), nums.end(), m2) &gt; nums.size() / 3) ans.push_back(m2); return ans; } }; Go func majorityElement(nums []int) []int { var n1, n2 int m1, m2 := 0, 1 for _, m := range nums { if m == m1 { n1++ } else if m == m2 { n2++ } else if n1 == 0 { m1, n1 = m, 1 } else if n2 == 0 { m2, n2 = m, 1 } else { n1, n2 = n1-1, n2-1 } } n1, n2 = 0, 0 for _, m := range nums { if m == m1 { n1++ } else if m == m2 { n2++ } } var ans []int if n1 &gt; len(nums)/3 { ans = append(ans, m1) } if n2 &gt; len(nums)/3 { ans = append(ans, m2) } return ans } C# public class Solution { public IList&lt;int&gt; MajorityElement(int[] nums) { int n1 = 0, n2 = 0; int m1 = 0, m2 = 1; foreach (int m in nums) { if (m == m1) { ++n1; } else if (m == m2) { ++n2; } else if (n1 == 0) { m1 = m; ++n1; } else if (n2 == 0) { m2 = m; ++n2; } else { --n1; --n2; } } var ans = new List&lt;int&gt;(); ans.Add(m1); ans.Add(m2); return ans.Where(m =&gt; nums.Count(n =&gt; n == m) &gt; nums.Length / 3).ToList(); } } PHP class Solution { /** * @param Integer[] $nums * @return Integer[] */ function majorityElement($nums) { $rs = []; $n = count($nums); for ($i = 0; $i &lt; $n; $i++) { $hashmap[$nums[$i]] += 1; if ($hashmap[$nums[$i]] &gt; $n / 3) { array_push($rs, $nums[$i]); } } return array_unique($rs); } }

