 230. 二叉搜索树中第 K 小的元素 English Version
题目描述 给定一个二叉搜索树的根节点 root ，和一个整数 k ，请你设计一个算法查找其中第&nbsp;k&nbsp;小的元素（k 从 1 开始计数）。
&nbsp;
示例 1：
输入：root = [3,1,4,null,2], k = 1 输出：1 示例 2：
输入：root = [5,3,6,2,4,null,null,1], k = 3 输出：3 &nbsp;
&nbsp;
提示：
树中的节点数为 n 。 1 &lt;= k &lt;= n &lt;= 104 0 &lt;= Node.val &lt;= 104 &nbsp;
进阶：如果二叉搜索树经常被修改（插入/删除操作）并且你需要频繁地查找第 k 小的值，你将如何优化算法？
解法 方法一：中序遍历 由于二叉搜索树的性质，中序遍历一定能得到升序序列，因此可以采用中序遍历找出第 k 小的元素。
Python3 # Definition for a binary tree node. # class TreeNode: # def __init__(self, val=0, left=None, right=None): # self.val = val # self.left = left # self.right = right class Solution: def kthSmallest(self, root: Optional[TreeNode], k: int) -&gt; int: stk = [] while root or stk: if root: stk.append(root) root = root.left else: root = stk.pop() k -= 1 if k == 0: return root.val root = root.right Java /** * Definition for a binary tree node. * public class TreeNode { * int val; * TreeNode left; * TreeNode right; * TreeNode() {} * TreeNode(int val) { this.val = val; } * TreeNode(int val, TreeNode left, TreeNode right) { * this.val = val; * this.left = left; * this.right = right; * } * } */ class Solution { public int kthSmallest(TreeNode root, int k) { Deque&lt;TreeNode&gt; stk = new ArrayDeque&lt;&gt;(); while (root != null || !stk.isEmpty()) { if (root != null) { stk.push(root); root = root.left; } else { root = stk.pop(); if (--k == 0) { return root.val; } root = root.right; } } return 0; } } C++ /** * Definition for a binary tree node. * struct TreeNode { * int val; * TreeNode *left; * TreeNode *right; * TreeNode() : val(0), left(nullptr), right(nullptr) {} * TreeNode(int x) : val(x), left(nullptr), right(nullptr) {} * TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {} * }; */ class Solution { public: int kthSmallest(TreeNode* root, int k) { stack&lt;TreeNode*&gt; stk; while (root || !stk.empty()) { if (root) { stk.push(root); root = root-&gt;left; } else { root = stk.top(); stk.pop(); if (--k == 0) return root-&gt;val; root = root-&gt;right; } } return 0; } }; Go /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func kthSmallest(root *TreeNode, k int) int { stk := []*TreeNode{} for root != nil || len(stk) &gt; 0 { if root != nil { stk = append(stk, root) root = root.Left } else { root = stk[len(stk)-1] stk = stk[:len(stk)-1] k-- if k == 0 { return root.Val } root = root.Right } } return 0 } TypeScript /** * Definition for a binary tree node. * class TreeNode { * val: number * left: TreeNode | null * right: TreeNode | null * constructor(val?: number, left?: TreeNode | null, right?: TreeNode | null) { * this.val = (val===undefined ? 0 : val) * this.left = (left===undefined ? null : left) * this.right = (right===undefined ? null : right) * } * } */ function kthSmallest(root: TreeNode | null, k: number): number { const dfs = (root: TreeNode | null) =&gt; { if (root == null) { return -1; } const { val, left, right } = root; const l = dfs(left); if (l !== -1) { return l; } k--; if (k === 0) { return val; } return dfs(right); }; return dfs(root); } Rust // Definition for a binary tree node. // #[derive(Debug, PartialEq, Eq)] // pub struct TreeNode { // pub val: i32, // pub left: Option&lt;Rc&lt;RefCell&lt;TreeNode&gt;&gt;&gt;, // pub right: Option&lt;Rc&lt;RefCell&lt;TreeNode&gt;&gt;&gt;, // } // // impl TreeNode { // #[inline] // pub fn new(val: i32) -&gt; Self { // TreeNode { // val, // left: None, // right: None // } // } // } use std::cell::RefCell; use std::rc::Rc; impl Solution { fn dfs(root: Option&lt;Rc&lt;RefCell&lt;TreeNode&gt;&gt;&gt;, res: &amp;mut Vec&lt;i32&gt;, k: usize) { if let Some(node) = root { let mut node = node.borrow_mut(); Self::dfs(node.left.take(), res, k); res.push(node.val); if res.len() &gt;= k { return; } Self::dfs(node.right.take(), res, k); } } pub fn kth_smallest(root: Option&lt;Rc&lt;RefCell&lt;TreeNode&gt;&gt;&gt;, k: i32) -&gt; i32 { let k = k as usize; let mut res: Vec&lt;i32&gt; = Vec::with_capacity(k); Self::dfs(root, &amp;mut res, k); res[k - 1] } } 方法二：预处理结点数 预处理每个结点作为根节点的子树的节点数。
这种算法可以用来优化频繁查找第 k 个树、而二叉搜索树本身不被修改的情况。
Python3 # Definition for a binary tree node. # class TreeNode: # def __init__(self, val=0, left=None, right=None): # self.val = val # self.left = left # self.right = right class BST: def __init__(self, root): self.cnt = Counter() self.root = root self.count(root) def kthSmallest(self, k): node = self.root while node: if self.cnt[node.left] == k - 1: return node.val if self.cnt[node.left] &lt; k - 1: k -= self.cnt[node.left] + 1 node = node.right else: node = node.left return 0 def count(self, root): if root is None: return 0 n = 1 + self.count(root.left) + self.count(root.right) self.cnt[root] = n return n class Solution: def kthSmallest(self, root: Optional[TreeNode], k: int) -&gt; int: bst = BST(root) return bst.kthSmallest(k) Java /** * Definition for a binary tree node. * public class TreeNode { * int val; * TreeNode left; * TreeNode right; * TreeNode() {} * TreeNode(int val) { this.val = val; } * TreeNode(int val, TreeNode left, TreeNode right) { * this.val = val; * this.left = left; * this.right = right; * } * } */ class Solution { public int kthSmallest(TreeNode root, int k) { BST bst = new BST(root); return bst.kthSmallest(k); } } class BST { private TreeNode root; private Map&lt;TreeNode, Integer&gt; cnt = new HashMap&lt;&gt;(); public BST(TreeNode root) { this.root = root; count(root); } public int kthSmallest(int k) { TreeNode node = root; while (node != null) { int v = node.left == null ? 0 : cnt.get(node.left); if (v == k - 1) { return node.val; } if (v &lt; k - 1) { node = node.right; k -= (v + 1); } else { node = node.left; } } return 0; } private int count(TreeNode root) { if (root == null) { return 0; } int n = 1 + count(root.left) + count(root.right); cnt.put(root, n); return n; } } C++ /** * Definition for a binary tree node. * struct TreeNode { * int val; * TreeNode *left; * TreeNode *right; * TreeNode() : val(0), left(nullptr), right(nullptr) {} * TreeNode(int x) : val(x), left(nullptr), right(nullptr) {} * TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {} * }; */ class BST { public: BST(TreeNode* root) : root(root) { count(root); } int kthSmallest(int k) { TreeNode* node = root; while (node) { int v = !node-&gt;left ? 0 : cnt[node-&gt;left]; if (v == k - 1) return node-&gt;val; if (v &lt; k - 1) { node = node-&gt;right; k -= (v + 1); } else node = node-&gt;left; } return 0; } private: TreeNode* root; unordered_map&lt;TreeNode*, int&gt; cnt; int count(TreeNode* root) { if (!root) return 0; int n = 1 + count(root-&gt;left) + count(root-&gt;right); cnt[root] = n; return n; } }; class Solution { public: int kthSmallest(TreeNode* root, int k) { BST bst(root); return bst.kthSmallest(k); } }; Go /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ type BST struct { cnt map[*TreeNode]int root *TreeNode } func newBST(root *TreeNode) *BST { var count func(*TreeNode) int cnt := map[*TreeNode]int{} count = func(root *TreeNode) int { if root == nil { return 0 } n := 1 + count(root.Left) + count(root.Right) cnt[root] = n return n } count(root) return &amp;BST{cnt, root} } func (bst *BST) kthSmallest(k int) int { node := bst.root for node != nil { v := 0 if node.Left != nil { v = bst.cnt[node.Left] } if v == k-1 { return node.Val } if v &lt; k-1 { k -= (v + 1) node = node.Right } else { node = node.Left } } return 0 } func kthSmallest(root *TreeNode, k int) int { bst := newBST(root) return bst.kthSmallest(k) }

 230. Kth Smallest Element in a BST 中文文档
Description Given the root of a binary search tree, and an integer k, return the kth smallest value (1-indexed) of all the values of the nodes in the tree.
