The number of nodes in the tree is n. 1 &lt;= k &lt;= n &lt;= 104 0 &lt;= Node.val &lt;= 104 &nbsp;
Follow up: If the BST is modified often (i.e., we can do insert and delete operations) and you need to find the kth smallest frequently, how would you optimize?
Solutions Solution 1 Python3 # Definition for a binary tree node. # class TreeNode: # def __init__(self, val=0, left=None, right=None): # self.val = val # self.left = left # self.right = right class Solution: def kthSmallest(self, root: Optional[TreeNode], k: int) -&gt; int: stk = [] while root or stk: if root: stk.append(root) root = root.left else: root = stk.pop() k -= 1 if k == 0: return root.val root = root.right Java /** * Definition for a binary tree node. * public class TreeNode { * int val; * TreeNode left; * TreeNode right; * TreeNode() {} * TreeNode(int val) { this.val = val; } * TreeNode(int val, TreeNode left, TreeNode right) { * this.val = val; * this.left = left; * this.right = right; * } * } */ class Solution { public int kthSmallest(TreeNode root, int k) { Deque&lt;TreeNode&gt; stk = new ArrayDeque&lt;&gt;(); while (root != null || !stk.isEmpty()) { if (root != null) { stk.push(root); root = root.left; } else { root = stk.pop(); if (--k == 0) { return root.val; } root = root.right; } } return 0; } } C++ /** * Definition for a binary tree node. * struct TreeNode { * int val; * TreeNode *left; * TreeNode *right; * TreeNode() : val(0), left(nullptr), right(nullptr) {} * TreeNode(int x) : val(x), left(nullptr), right(nullptr) {} * TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {} * }; */ class Solution { public: int kthSmallest(TreeNode* root, int k) { stack&lt;TreeNode*&gt; stk; while (root || !stk.empty()) { if (root) { stk.push(root); root = root-&gt;left; } else { root = stk.top(); stk.pop(); if (--k == 0) return root-&gt;val; root = root-&gt;right; } } return 0; } }; Go /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func kthSmallest(root *TreeNode, k int) int { stk := []*TreeNode{} for root != nil || len(stk) &gt; 0 { if root != nil { stk = append(stk, root) root = root.Left } else { root = stk[len(stk)-1] stk = stk[:len(stk)-1] k-- if k == 0