e node: if self.cnt[node.left] == k - 1: return node.val if self.cnt[node.left] &lt; k - 1: k -= self.cnt[node.left] + 1 node = node.right else: node = node.left return 0 def count(self, root): if root is None: return 0 n = 1 + self.count(root.left) + self.count(root.right) self.cnt[root] = n return n class Solution: def kthSmallest(self, root: Optional[TreeNode], k: int) -&gt; int: bst = BST(root) return bst.kthSmallest(k) Java /** * Definition for a binary tree node. * public class TreeNode { * int val; * TreeNode left; * TreeNode right; * TreeNode() {} * TreeNode(int val) { this.val = val; } * TreeNode(int val, TreeNode left, TreeNode right) { * this.val = val; * this.left = left; * this.right = right; * } * } */ class Solution { public int kthSmallest(TreeNode root, int k) { BST bst = new BST(root); return bst.kthSmallest(k); } } class BST { private TreeNode root; private Map&lt;TreeNode, Integer&gt; cnt = new HashMap&lt;&gt;(); public BST(TreeNode root) { this.root = root; count(root); } public int kthSmallest(int k) { TreeNode node = root; while (node != null) { int v = node.left == null ? 0 : cnt.get(node.left); if (v == k - 1) { return node.val; } if (v &lt; k - 1) { node = node.right; k -= (v + 1); } else { node = node.left; } } return 0; } private int count(TreeNode root) { if (root == null) { return 0; } int n = 1 + count(root.left) + count(root.right); cnt.put(root, n); return n; } } C++ /** * Definition for a binary tree node. * struct TreeNode { * int val; * TreeNode *left; * TreeNode *right; * TreeNode() : val(0), left(nullptr), right(nullptr) {} * TreeNode(int x) : val(x), left(nullptr), right(nullptr) {} * TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {} * }; */ class BST { public: BST(TreeNode* root) : root(root) { count(root); } int kthSmallest(int k) { TreeNode* node = root; while (node) { int v = !node-&gt;left ? 0 : cnt[node-&gt;left]; if (v == k - 1) return node-&gt;val; if (v &lt; k - 1) { node = node-&gt;right; k -= (v + 1); } else node = node-&gt;left; } return 0; } private: TreeNode* root; unordered_map&lt;TreeNode*, int&gt; cnt; int count(TreeNode* root) { if (!root) return 0; int n = 1 + count(root-&gt;left) + count(root-&gt;right); cnt[root] = n; return n; } }; class Solution { public: int kthSmallest(TreeNode* root, int k) { BST bst(root); return bst.kthSmallest(k); } }; Go /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ type BST struct { cnt map[*TreeNode]int root *TreeNode } func newBST(root *TreeNode) *BST { var count func(*TreeNode) int cnt := map[*TreeNode]int{} count = func(root *TreeNode) int { if root == nil { return 0 } n := 1 + count(root.Left) + count(root.Right) cnt[root] = n return n } count(root) return &amp;BST{cnt, root} } func (bst *BST) kthSmallest(k int) int { node := bst.root for node != nil { v := 0 if node.Left != nil { v = bst.cnt[node.Left] } if v == k-1 { return node.Val } if v &lt; k-1 { k -= (v + 1) node = node.Right } else { node = node.Left } } return 0 } func kthSmallest(root *TreeNode, k int) int { bst := newBST(root) return bst.kthSmallest(k) }

 234. 回文链表 English Version
题目描述 给你一个单链表的头节点 head ，请你判断该链表是否为回文链表。如果是，返回 true ；否则，返回 false 。
&nbsp;
示例 1：
输入：head = [1,2,2,1] 输出：true 示例 2：
输入：head = [1,2] 输出：false &nbsp;
提示：
链表中节点数目在范围[1, 105] 内 0 &lt;= Node.val &lt;= 9 &nbsp;
进阶：你能否用&nbsp;O(n) 时间复杂度和 O(1) 空间复杂度解决此题？
解法 方法一：快慢指针 我们可以先用快慢指针找到链表的中点，接着反转右半部分的链表。然后同时遍历前后两段链表，若前后两段链表节点对应的值不等，说明不是回文链表，否则说明是回文链表。
时间复杂度 $O(n)$，其中 $n$ 为链表的长度。空间复杂度 $O(1)$。
Python3 # Definition for singly-linked list. # class ListNode: # def __init__(self, val=0, next=None): # self.val = val # self.next = next class Solution: def isPalindrome(self, head: Optional[ListNode]) -&gt; bool: slow, fast = head, head.next while fast and fast.next: slow, fast = slow.next, fast.next.next pre, cur = None, slow.next while cur: t = cur.next cur.next = pre pre, cur = cur, t while pre: if pre.val != head.val: return False pre, head = pre.next, head.next return True Java /** * Definition for singly-linked list. * public class ListNode { * int val; * ListNode next; * ListNode() {} * ListNode(int val) { this.val = val; } * ListNode(int val, ListNode next) { this.val = val; this.next = next; } * } */ class Solution { public boolean isPalindrome(ListNode head) { ListNode slow = head; ListNode fast = head.next; while (fast != null &amp;&amp; fast.next != null) { slow = slow.next; fast = fast.next.next; } ListNode cur = slow.next; slow.next = null; ListNode pre = null; while (cur != null) { ListNode t = cur.next; cur.next = pre; pre = cur; cur = t; } while (pre != null) { if (pre.val != head.val) { return false; } pre = pre.next; head = head.next; } return true; } } C++ /** * Definition for singly-linked list. * struct ListNode { * int val; * ListNode *next; * ListNode() : val(0), next(nullptr) {} * ListNode(int x) : val(x), next(nullptr) {} * ListNode(int x, ListNode *next) : val(x), next(next) {} * }; */ class Solution { public: bool isPalindrome(ListNode* head) { ListNode* slow = head; ListNode* fast = head-&gt;next; while (fast &amp;&amp; fast-&gt;next) { slow = slow-&gt;next; fast = fast-&gt;next-&gt;next; } ListNode* pre = nullptr; ListNode* cur = slow-&gt;next; while (cur) { ListNode* t = cur-&gt;next; cur-&gt;next = pre; pre = cur; cur = t; } while (pre) { if (pre-&gt;val != head-&gt;val) return false; pre = pre-&gt;next; head = head-&gt;next; } return true; } }; Go /** * Definition for singly-linked list. * type ListNode struct { * Val int * Next *ListNode * } */ func isPalindrome(head *ListNode) bool { slow, fast := head, head.Next for fast != nil &amp;&amp; fast.Next != nil { slow, fast = slow.Next, fast.Next.Next } var pre *ListNode cur := slow.Next for cur != nil { t := cur.Next cur.Next = pre pre = cur cur = t } for pre != nil { if pre.Val != head.Val { return false } pre, head = pre.Next, head.Next } return true } TypeScript /** * Definition for singly-linked list. * class ListNode { * val: number * next: ListNode | null * constructor(val?: number, next?: ListNode | null) { * this.val = (val===undefined ? 0 : val) * this.next = (next===undefined ? null : next) * } * } */ function isPalindrome(head: ListNode | null): boolean { let slow: ListNode = head, fast: ListNode = head.next; while (fast != null &amp;&amp; fast.next != null) { slow = slow.next; fast = fast.next.next; } let cur: ListNode = slow.next; slow.next = null; let prev: ListNode = null; while (cur != null) { let t: ListNode = cur.next; cur.next = prev; prev = cur; cur = t; } while (prev != null) { if (prev.val != head.val) return false; prev = prev.next; head = head.next; } return true; } JavaScript /** * Definition for singly-linked list. * function ListNode(val, next) { * this.val = (val===undefined ? 0 : val) * this.next = (next===undefined ? null : next) * } */ /** * @param {ListNode} head * @return {boolean} */ var isPalindrome = function (head) { let slow = head; let fast = head.next; while (fast &amp;&amp; fast.next) { slow = slow.next; fast = fast.next.next; } let cur = slow.next; slow.next = null; let pre = null; while (cur) { let t = cur.next; cur.next = pre; pre = cur; cur = t; } while (pre) { if (pre.val !== head.val) { return false; } pre = pre.next; head = head.next; } return true; }; C# /** * Definition for singly-linked list. * public class ListNode { * public int val; * public ListNode next; * public ListNode(int val=0, ListNode next=null) { * this.val = val; * this.next = next; * } * } */ public class Solution { public bool IsPalindrome(ListNode head) { ListNode slow = head; ListNode fast = head.next; while (fast != null &amp;&amp; fast.next != null) { slow = slow.next; fast = fast.next.next; } ListNode cur = slow.next; slow.next = null; ListNode pre = null; while (cur != null) { ListNode t = cur.next; cur.next = pre; pre = cur; cur = t; } while (pre != null) { if (pre.val != head.val) { return false; } pre = pre.next; head = head.next; } return true; } }

 234. Palindrome Linked List 中文文档
Description Given the head of a singly linked list, return true if it is a palindrome or false otherwise.
&nbsp;
Example 1:
Input: head = [1,2,2,1] Output: true Example 2:
Input: head = [1,2] Output: false &nbsp;
Constraints:
The number of nodes in the list is in the range [1, 105]. 0 &lt;= Node.val &lt;= 9 &nbsp;
Follow up: Could you do it in O(n) time and O(1) space? Solutions Solution 1: Fast and Slow Pointers We can use fast and slow pointers to find the middle of the linked list, then reverse the right half of the list. After that, we traverse both halves simultaneously, checking if the corresponding node values are equal. If any pair of values is unequal, it&rsquo;s not a palindrome linked list; otherwise, it is a palindrome linked list.
The time complexity is $O(n)$, where $n$ is the length of the linked list. The space complexity is $O(1)$.
Python3 # Definition for singly-linked list. # class ListNode: # def __init__(self, val=0, next=None): # self.val = val # self.next = next class Solution: def isPalindrome(self, head: Optional[ListNode]) -&gt; bool: slow, fast = head, head.next while fast and fast.next: slow, fast = slow.next, fast.next.next pre, cur = None, slow.next while cur: t = cur.next cur.next = pre pre, cur = cur, t while pre: if pre.val != head.val: return False pre, head = pre.next, head.next return True Java /** * Definition for singly-linked list. * public class ListNode { * int val; * ListNode next; * ListNode() {} * ListNode(int val) { this.val = val; } * ListNode(int val, ListNode next) { this.val = val; this.next = next; } * } */ class Solution { public boolean isPalindrome(ListNode head) { ListNode slow = head; ListNode fast = head.next; while (fast != null &amp;&amp; fast.next != null) { slow = slow.next; fast = fast.next.next; } ListNode cur = slow.next; slow.next = null; ListNode pre = null; while (cur != null) { ListNode t = cur.next; cur.next = pre; pre = cur; cur = t; } while (pre != null) { if (pre.val != head.val) { return false; } pre = pre.next; head = head.next; } return true; } } C++ /** * Definition for singly-linked list. * struct ListNode { * int val; * ListNode *next; * ListNode() : val(0), next(nullptr) {} * ListNode(int x) : val(x), next(nullptr) {} * ListNode(int x, ListNode *next) : val(x), next(next) {} * }; */ class Solution { public: bool isPalindrome(ListNode* head) { ListNode* slow = head; ListNode* fast = head-&gt;next; while (fast &amp;&amp; fast-&gt;next) { slow = slow-&gt;next; fast = fast-&gt;next-&gt;next; } ListNode* pre = nullptr; ListNode* cur = slow-&gt;next; while (cur) { ListNode* t = cur-&gt;next; cur-&gt;next = pre; pre = cur; cur = t; } while (pre) { if (pre-&gt;val != head-&gt;val) return false; pre = pre-&gt;next; head = head-&gt;next; } return true; } }; Go /** * Definition for singly-linked list. * type ListNode struct { * Val int * Next *ListNode * } */ func isPalindrome(head *ListNode) bool { slow, fast := head, head.Next for fast != nil &amp;&amp; fast.Next != nil { slow, fast = slow.Next, fast.Next.Next } var pre *ListNode cur := slow.Next for cur != nil { t := cur.Next cur.Next = pre pre = cur cur = t } for pre != nil { if pre.Val != head.Val { return false } pre, head = pre.Next, head.Next } return true } TypeScript /** * Definition for singly-linked list. * class ListNode { * val: number * next: ListNode | null * constructor(val?: number, next?: ListNode | null) { * this.val = (val===undefined ? 0 : val) * this.next = (next===undefined ? null : next) * } * } */ function isPalindrome(head: ListNode | null): boolean { let slow: ListNode = head, fast: ListNode = head.next; while (fast != null &amp;&amp; fast.next != null) { slow = slow.next; fast = fast.next.next; } let cur: ListNode = slow.next; slow.next = null; let prev: ListNode = null; while (cur != null) { let t: ListNode = cur.next; cur.next = prev; prev = cur; cur = t; } while (prev != null) { if (prev.val != head.val) return false; prev = prev.next; head = head.next; } return true; } JavaScript /** * Definition for singly-linked list. * function ListNode(val, next) { * this.val = (val===undefined ? 0 : val) * this.next = (next===undefined ? null : next) * } */ /** * @param {ListNode} head * @return {boolean} */ var isPalindrome = function (head) { let slow = head; let fast = head.next; while (fast &amp;&amp; fast.next) { slow = slow.next; fast = fast.next.next; } let cur = slow.next; slow.next = null; let pre = null; while (cur) { let t = cur.next; cur.next = pre; pre = cur; cur = t; } while (pre) { if (pre.val !== head.val) { return false; } pre = pre.next; head = head.next; } return true; }; C# /** * Definition for singly-linked list. * public class ListNode { * public int val; * public ListNode next; * public ListNode(int val=0, ListNode next=null) { * this.val = val; * this.next = next; * } * } */ public class Solution { public bool IsPalindrome(ListNode head) { ListNode slow = head; ListNode fast = head.next; while (fast != null &amp;&amp; fast.next != null) { slow = slow.next; fast = fast.next.next; } ListNode cur = slow.next; slow.next = null; ListNode pre = null; while (cur != null) { ListNode t = cur.next; cur.next = pre; pre = cur; cur = t; } while (pre != null) { if (pre.val != head.val) { return false; } pre = pre.next; head = head.next; } return true; } }

 236. Lowest Common Ancestor of a Binary Tree 中文文档
Description Given a binary tree, find the lowest common ancestor (LCA) of two given nodes in the tree.
According to the definition of LCA on Wikipedia: &ldquo;The lowest common ancestor is defined between two nodes p and q as the lowest node in T that has both p and q as descendants (where we allow a node to be a descendant of itself).&rdquo;
&nbsp;
Example 1:
Input: root = [3,5,1,6,2,0,8,null,null,7,4], p = 5, q = 1 Output: 3 Explanation: The LCA of nodes 5 and 1 is 3. Example 2:
Input: root = [3,5,1,6,2,0,8,null,null,7,4], p = 5, q = 4 Output: 5 Explanation: The LCA of nodes 5 and 4 is 5, since a node can be a descendant of itself according to the LCA definition. Example 3:
Input: root = [1,2], p = 1, q = 2 Output: 1 &nbsp;
Constraints:
The number of nodes in the tree is in the range [2, 105]. -109 &lt;= Node.val &lt;= 109 All Node.val are unique. p != q p and q will exist in the tree. Solutions Solution 1: Recursion We recursively traverse the binary tree:
If the current node is null or equals to $p$ or $q$, then we return the current node;
Otherwise, we recursively traverse the left and right subtrees, and record the returned results as $left$ and $right$. If both $left$ and $right$ are not null, it means that $p$ and $q$ are in the left and right subtrees respectively, so the current node is the nearest common ancestor; If only one of $left$ and $right$ is not null, we return the one that is not null.
The time complexity is $O(n)$, and the space complexity is $O(n)$. Here, $n$ is the number of nodes in the binary tree.
Python3 # Definition for a binary tree node. # class TreeNode: # def __init__(self, x): # self.val = x # self.left = None # self.right = None class Solution: def lowestCommonAncestor( self, root: &#34;TreeNode&#34;, p: &#34;TreeNode&#34;, q: &#34;TreeNode&#34; ) -&gt; &#34;TreeNode&#34;: if root in (None, p, q): return root left = self.lowestCommonAncestor(root.left, p, q) right = self.lowestCommonAncestor(root.right, p, q) return root if left and right else (left or right) Java /** * Definition for a binary tree node. * public class TreeNode { * int val; * TreeNode left; * TreeNode right; * TreeNode(int x) { val = x; } * } */ class Solution { public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) { if (root == null || root == p || root == q) { return root; } var left = lowestCommonAncestor(root.left, p, q); var right = lowestCommonAncestor(root.right, p, q); if (left != null &amp;&amp; right != null) { return root; } return left == null ? right : left; } } C++ /** * Definition for a binary tree node. * struct TreeNode { * int val; * TreeNode *left; * TreeNode *right; * TreeNode(int x) : val(x), left(NULL), right(NULL) {} * }; */ class Solution { public: TreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) { if (root == nullptr || root == p || root == q) { return root; } auto left = lowestCommonAncestor(root-&gt;left, p, q); auto right = lowestCommonAncestor(root-&gt;right, p, q); if (left &amp;&amp; right) { return root; } return left ? left : right; } }; Go /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func lowestCommonAncestor(root, p, q *TreeNode) *TreeNode { if root == nil || root == p || root == q { return root } left := lowestCommonAncestor(root.Left, p, q) right := lowestCommonAncestor(root.Right, p, q) if left != nil &amp;&amp; right != nil { return root } if left != nil { return left } return right } TypeScript /** * Definition for a binary tree node. * class TreeNode { * val: number * left: TreeNode | null * right: TreeNode | null * constructor(val?: number, left?: TreeNode | null, right?: TreeNode | null) { * this.val = (val===undefined ? 0 : val) * this.left = (left===undefined ? null : left) * this.right = (right===undefined ? null : right) * } * } */ function lowestCommonAncestor( root: TreeNode | null, p: TreeNode | null, q: TreeNode | null, ): TreeNode | null { if (!root || root === p || root === q) { return root; } const left = lowestCommonAncestor(root.left, p, q); const right = lowestCommonAncestor(root.right, p, q); return left &amp;&amp; right ? root : left || right; } Rust // Definition for a binary tree node. // #[derive(Debug, PartialEq, Eq)] // pub struct TreeNode { // pub val: i32, // pub left: Option&lt;Rc&lt;RefCell&lt;TreeNode&gt;&gt;&gt;, // pub right: Option&lt;Rc&lt;RefCell&lt;TreeNode&gt;&gt;&gt;, // } // // impl TreeNode { // #[inline] // pub fn new(val: i32) -&gt; Self { // TreeNode { // val, // left: None, // right: None // } // } // } use std::cell::RefCell; use std::rc::Rc; impl Solution { pub fn lowest_common_ancestor( root: Option&lt;Rc&lt;RefCell&lt;TreeNode&gt;&gt;&gt;, p: Option&lt;Rc&lt;RefCell&lt;TreeNode&gt;&gt;&gt;, q: Option&lt;Rc&lt;RefCell&lt;TreeNode&gt;&gt;&gt;, ) -&gt; Option&lt;Rc&lt;RefCell&lt;TreeNode&gt;&gt;&gt; { if root.is_none() || root == p || root == q { return root; } let left = Self::lowest_common_ancestor( root.as_ref().unwrap().borrow().left.clone(), p.clone(), q.clone(), ); let right = Self::lowest_common_ancestor( root.as_ref().unwrap().borrow().right.clone(), p.clone(), q.clone(), ); if left.is_some() &amp;&amp; right.is_some() { return root; } if left.is_none() { return right; } return left; } } JavaScript /** * Definition for a binary tree node. * function TreeNode(val) { * this.val = val; * this.left = this.right = null; * } */ /** * @param {TreeNode} root * @param {TreeNode} p * @param {TreeNode} q * @return {TreeNode} */ var lowestCommonAncestor = function (root, p, q) { if (!root || root === p || root === q) { return root; } const left = lowestCommonAncestor(root.left, p, q); const right = lowestCommonAncestor(root.right, p, q); return left &amp;&amp; right ? root : left || right; };

 241. 为运算表达式设计优先级 English Version
题目描述 给你一个由数字和运算符组成的字符串&nbsp;expression ，按不同优先级组合数字和运算符，计算并返回所有可能组合的结果。你可以 按任意顺序 返回答案。
生成的测试用例满足其对应输出值符合 32 位整数范围，不同结果的数量不超过 104 。
&nbsp;
示例 1：
输入：expression = "2-1-1" 输出：[0,2] 解释： ((2-1)-1) = 0 (2-(1-1)) = 2 示例 2：
输入：expression = "2*3-4*5" 输出：[-34,-14,-10,-10,10] 解释： (2*(3-(4*5))) = -34 ((2*3)-(4*5)) = -14 ((2*(3-4))*5) = -10 (2*((3-4)*5)) = -10 (((2*3)-4)*5) = 10 &nbsp;
提示：
1 &lt;= expression.length &lt;= 20 expression 由数字和算符 '+'、'-' 和 '*' 组成。 输入表达式中的所有整数值在范围 [0, 99]&nbsp; 输入表达式中的所有整数都没有前导&nbsp;'-'&nbsp;或&nbsp;'+' 表示符号。 解法 方法一：记忆化搜索 Python3 class Solution: def diffWaysToCompute(self, expression: str) -&gt; List[int]: @cache def dfs(exp): if exp.isdigit(): return [int(exp)] ans = [] for i, c in enumerate(exp): if c in &#39;-+*&#39;: left, right = dfs(exp[:i]), dfs(exp[i + 1 :]) for a in left: for b in right: if c == &#39;-&#39;: ans.append(a - b) elif c == &#39;+&#39;: ans.append(a + b) else: ans.append(a * b) return ans return dfs(expression) Java class Solution { private static Map&lt;String, List&lt;Integer&gt;&gt; memo = new HashMap&lt;&gt;(); public List&lt;Integer&gt; diffWaysToCompute(String expression) { return dfs(expression); } private List&lt;Integer&gt; dfs(String exp) { if (memo.containsKey(exp)) { return memo.get(exp); } List&lt;Integer&gt; ans = new ArrayList&lt;&gt;(); if (exp.length() &lt; 3) { ans.add(Integer.parseInt(exp)); return ans; } for (int i = 0; i &lt; exp.length(); ++i) { char c = exp.charAt(i); if (c == &#39;-&#39; || c == &#39;+&#39; || c == &#39;*&#39;) { List&lt;Integer&gt; left = dfs(exp.substring(0, i)); List&lt;Integer&gt; right = dfs(exp.substring(i + 1)); for (int a : left) { for (int b : right) { if (c == &#39;-&#39;) { ans.add(a - b); } else if (c == &#39;+&#39;) { ans.add(a + b); } else { ans.add(a * b); } } } } } memo.put(exp, ans); return ans; } } C++ class Solution { public: vector&lt;int&gt; diffWaysToCompute(string expression) { return dfs(expression); } vector&lt;int&gt; dfs(string exp) { if (memo.count(exp)) return memo[exp]; if (exp.size() &lt; 3) return {stoi(exp)}; vector&lt;int&gt; ans; int n = exp.size(); for (int i = 0; i &lt; n; ++i) { char c = exp[i]; if (c == &#39;-&#39; || c == &#39;+&#39; || c == &#39;*&#39;) { vector&lt;int&gt; left = dfs(exp.substr(0, i)); vector&lt;int&gt; right = dfs(exp.substr(i + 1, n - i - 1)); for (int&amp; a : left) { for (int&amp; b : right) { if (c == &#39;-&#39;) ans.push_back(a - b); else if (c == &#39;+&#39;) ans.push_back(a + b); else ans.push_back(a * b); } } } } memo[exp] = ans; return ans; } private: unordered_map&lt;string, vector&lt;int&gt;&gt; memo; }; Go var memo = map[string][]int{} func diffWaysToCompute(expression string) []int { return dfs(expression) } func dfs(exp string) []int { if v, ok := memo[exp]; ok { return v } if len(exp) &lt; 3 { v, _ := strconv.Atoi(exp) return []int{v} } ans := []int{} for i, c := range exp { if c == &#39;-&#39; || c == &#39;+&#39; || c == &#39;*&#39; { left, right := dfs(exp[:i]), dfs(exp[i+1:]) for _, a := range left { for _, b := range right { if c == &#39;-&#39; { ans = append(ans, a-b) } else if c == &#39;+&#39; { ans = append(ans, a+b) } else { ans = append(ans, a*b) } } } } } memo[exp] = ans return ans } C# using System.Collections.Generic; public class Solution { public IList&lt;int&gt; DiffWaysToCompute(string input) { var values = new List&lt;int&gt;(); var operators = new List&lt;char&gt;(); var sum = 0; foreach (var ch in input) { if (ch == &#39;+&#39; || ch == &#39;-&#39; || ch == &#39;*&#39;) { values.Add(sum); operators.Add(ch); sum = 0; } else { sum = sum * 10 + ch - &#39;0&#39;; } } values.Add(sum); var f = new List&lt;int&gt;[values.Count, values.Count]; for (var i = 0; i &lt; values.Count; ++i) { f[i, i] = new List&lt;int&gt; { values[i] }; } for (var diff = 1; diff &lt; values.Count; ++diff) { for (var left = 0; left + diff &lt; values.Count; ++left) { var right = left + diff; f[left, right] = new List&lt;int&gt;(); for (var i = left; i &lt; right; ++i) { foreach (var leftValue in f[left, i]) { foreach (var rightValue in f[i + 1, right]) { switch (operators[i]) { case &#39;+&#39;: f[left, right].Add(leftValue + rightValue); break; case &#39;-&#39;: f[left, right].Add(leftValue - rightValue); break; case &#39;*&#39;: f[left, right].Add(leftValue * rightValue); break; } } } } } } return f[0, values.Count - 1]; } }

