-231 &lt;= n &lt;= 231 - 1 解法 方法一 Python3 class Solution: def isUgly(self, n: int) -&gt; bool: if n &lt; 1: return False for x in [2, 3, 5]: while n % x == 0: n //= x return n == 1 Java class Solution { public boolean isUgly(int n) { if (n &lt; 1) return false; while (n % 2 == 0) { n /= 2; } while (n % 3 == 0) { n /= 3; } while (n % 5 == 0) { n /= 5; } return n == 1; } } C++ class Solution { public: bool isUgly(int n) { if (n &lt; 1) return false; while (n % 2 == 0) { n /= 2; } while (n % 3 == 0) { n /= 3; } while (n % 5 == 0) { n /= 5; } return n == 1; } }; Go func isUgly(n int) bool { if n &lt; 1 { return false } for _, x := range []int{2, 3, 5} { for n%x == 0 { n /= x } } return n == 1 } JavaScript /** * @param {number} n * @return {boolean} */ var isUgly = function (n) { if (n &lt; 1) return false; while (n % 2 === 0) { n /= 2; } while (n % 3 === 0) { n /= 3; } while (n % 5 === 0) { n /= 5; } return n === 1; }; PHP class Solution { /** * @param Integer $n * @return Boolean */ function isUgly($n) { while ($n) { if ($n % 2 == 0) { $n = $n / 2; } elseif ($n % 3 == 0) { $n = $n / 3; } elseif ($n % 5 == 0) { $n = $n / 5; } else { break; } } return $n == 1; } }

