Input: n = 1 Output: 1 Explanation: 1 has no prime factors, therefore all of its prime factors are limited to 2, 3, and 5. &nbsp;
Constraints:
1 &lt;= n &lt;= 1690 Solutions Solution 1 Python3 class Solution: def nthUglyNumber(self, n: int) -&gt; int: h = [1] vis = {1} ans = 1 for _ in range(n): ans = heappop(h) for v in [2, 3, 5]: nxt = ans * v if nxt not in vis: vis.add(nxt) heappush(h, nxt) return ans Java class Solution { public int nthUglyNumber(int n) { Set&lt;Long&gt; vis = new HashSet&lt;&gt;(); PriorityQueue&lt;Long&gt; q = new PriorityQueue&lt;&gt;(); int[] f = new int[] {2, 3, 5}; q.offer(1L); vis.add(1L); long ans = 0; while (n-- &gt; 0) { ans = q.poll(); for (int v : f) { long next = ans * v; if (vis.add(next)) { q.offer(next); } } } return (int) ans; } } C++ class Solution { public: int nthUglyNumber(int n) { priority_queue&lt;long, vector&lt;long&gt;, greater&lt;long&gt;&gt; q; q.push(1l); unordered_set&lt;long&gt; vis{{1l}}; long ans = 1; vector&lt;int&gt; f = {2, 3, 5}; while (n--) { ans = q.top(); q.pop(); for (int&amp; v : f) { long nxt = ans * v; if (!vis.count(nxt)) { vis.insert(nxt); q.push(nxt); } } } return (int) ans; } }; Go func nthUglyNumber(n int) int { h := IntHeap([]int{1}) heap.Init(&amp;h) ans := 1 vis := map[int]bool{1: true} for n &gt; 0 { ans = heap.Pop(&amp;h).(int) for _, v := range []int{2, 3, 5} { nxt := ans * v if !vis[nxt] { vis[nxt] = true heap.Push(&amp;h, nxt) } } n-- } return ans } type IntHeap []int func (h IntHeap) Len() int { return len(h) } func (h IntHeap) Less(i, j int) bool { return h[i] &lt; h[j] } func (h IntHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] } func (h *IntHeap) Push(x any) { *h = append(*h, x.(int)) } func (h *IntHeap) Pop() any { old := *h n := len(old) x := old[n-1] *h = old[0 : n-1] return x } JavaScript /** * @param {number} n * @return {number} */ var nthUglyNumber = function (n) { let dp = [1]; let p2 = 0, p3 = 0, p5 = 0; for (let i = 1; i &lt; n; ++i) { const next2 = dp[p2] * 2, next3 = dp[p3] * 3, next5 = dp[p5] * 5; dp[i] = Math.min(next2, Math.min(next3, next5)); if (dp[i] == next2) ++p2; if (dp[i] == next3) ++p3; if (dp[i] == next5) ++p5; dp.push(dp[i]); } return dp[n - 1]; }; C# public class Solution { public int NthUglyNumber(int n) { int[] dp = new int[n]; dp[0] = 1; int p2 = 0, p3 = 0, p5 = 0; for (int i = 1; i &lt; n; ++i) { int next2 = dp[p2] * 2, next3 = dp[p3] * 3, next5 = dp[p5] * 5; dp[i] = Math.Min(next2, Math.Min(next3, next5)); if (dp[i] == next2) { ++p2; } if (dp[i] == next3) { ++p3; } if (dp[i] == next5) { ++p5; } } return dp[n - 1]; } } Solution 2 Python3 class Solution: def nthUglyNumber(self, n: int) -&gt; int: dp = [1] * n p2 = p3 = p5 = 0 for i in range(1, n): next2, next3, next5 = dp[p2] * 2, dp[p3] * 3, dp[p5] * 5 dp[i] = min(next2, next3, next5) if dp[i] == next2: p2 += 1 if dp[i] == next3: p3 += 1 if dp[i] == next5: p5 += 1 return dp[-1] Java class Solution { public int nthUglyNumber(int n) { int[] dp = new int[n]; dp[0] = 1; int p2 = 0, p3 = 0, p5 = 0; for (int i = 1; i &lt; n; ++i) { int next2 = dp[p2] * 2, next3 = dp[p3] * 3, next5 = dp[p5] * 5; dp[i] = Math.min(next2, Math.min(next3, next5)); if (dp[i] == next2) ++p2; if (dp[i] == next3) ++p3; if (dp[i] == next5) ++p5; } return dp[n - 1]; } } C++ class Solution { public: int nthUglyNumber(int n) { vector&lt;int&gt; dp(n); dp[0] = 1; int p2 = 0, p3 = 0, p5 = 0; for (int i = 1; i &lt; n; ++i) { int next2 = dp[p2] * 2, next3 = dp[p3] * 3, next5 = dp[p5] * 5; dp[i] = min(next2, min(next3, next5)); if (dp[i] == next2) ++p2; if (dp[i] == next3) ++p3; if (dp[i] == next5) ++p5; } return dp[n - 1]; } }; Go func nthUglyNumber(n int) int { dp := make([]int, n) dp[0] = 1 p2, p3, p5 := 0, 0, 0 for i := 1; i &lt; n; i++ { next2, next3, next5 := dp[p2]*2, dp[p3]*3, dp[p5]*5 dp[i] = min(next2, min(next3, next5)) if dp[i] == next2 { p2++ } if dp[i] == next3 { p3++ } if dp[i] == next5 { p5++ } } return dp[n-1] }

 265. Paint House II 🔒 中文文档
Description There are a row of n houses, each house can be painted with one of the k colors. The cost of painting each house with a certain color is different. You have to paint all the houses such that no two adjacent houses have the same color.
The cost of painting each house with a certain color is represented by an n x k cost matrix costs.
For example, costs[0][0] is the cost of painting house 0 with color 0; costs[1][2] is the cost of painting house 1 with color 2, and so on... Return the minimum cost to paint all houses.
&nbsp;
Example 1:
Input: costs = [[1,5,3],[2,9,4]] Output: 5 Explanation: Paint house 0 into color 0, paint house 1 into color 2. Minimum cost: 1 + 4 = 5; Or paint house 0 into color 2, paint house 1 into color 0. Minimum cost: 3 + 2 = 5. Example 2:
Input: costs = [[1,3],[2,4]] Output: 5 &nbsp;
Constraints:
costs.length == n costs[i].length == k 1 &lt;= n &lt;= 100 2 &lt;= k &lt;= 20 1 &lt;= costs[i][j] &lt;= 20 &nbsp;
Follow up: Could you solve it in O(nk) runtime?
Solutions Solution 1 Python3 class Solution: def minCostII(self, costs: List[List[int]]) -&gt; int: n, k = len(costs), len(costs[0]) f = costs[0][:] for i in range(1, n): g = costs[i][:] for j in range(k): t = min(f[h] for h in range(k) if h != j) g[j] += t f = g return min(f) Java class Solution { public int minCostII(int[][] costs) { int n = costs.length, k = costs[0].length; int[] f = costs[0].clone(); for (int i = 1; i &lt; n; ++i) { int[] g = costs[i].clone(); for (int j = 0; j &lt; k; ++j) { int t = Integer.MAX_VALUE; for (int h = 0; h &lt; k; ++h) { if (h != j) { t = Math.min(t, f[h]); } } g[j] += t; } f = g; } return Arrays.stream(f).min().getAsInt(); } } C++ class Solution { public: int minCostII(vector&lt;vector&lt;int&gt;&gt;&amp; costs) { int n = costs.size(), k = costs[0].size(); vector&lt;int&gt; f = costs[0]; for (int i = 1; i &lt; n; ++i) { vector&lt;int&gt; g = costs[i]; for (int j = 0; j &lt; k; ++j) { int t = INT_MAX; for (int h = 0; h &lt; k; ++h) { if (h != j) { t = min(t, f[h]); } } g[j] += t; } f = move(g); } return *min_element(f.begin(), f.end()); } }; Go func minCostII(costs [][]int) int { n, k := len(costs), len(costs[0]) f := cp(costs[0]) for i := 1; i &lt; n; i++ { g := cp(costs[i]) for j := 0; j &lt; k; j++ { t := math.MaxInt32 for h := 0; h &lt; k; h++ { if h != j &amp;&amp; t &gt; f[h] { t = f[h] } } g[j] += t } f = g } return slices.Min(f) } func cp(arr []int) []int { t := make([]int, len(arr)) copy(t, arr) return t }

 267. Palindrome Permutation II 🔒 中文文档
Description Given a string s, return all the palindromic permutations (without duplicates) of it.
You may return the answer in any order. If s has no palindromic permutation, return an empty list.
&nbsp;
Example 1:
Input: s = "aabb" Output: ["abba","baab"] Example 2:
Input: s = "abc" Output: [] &nbsp;
Constraints:
1 &lt;= s.length &lt;= 16 s consists of only lowercase English letters. Solutions Solution 1 Python3 class Solution: def generatePalindromes(self, s: str) -&gt; List[str]: def dfs(t): if len(t) == len(s): ans.append(t) return for c, v in cnt.items(): if v &gt; 1: cnt[c] -= 2 dfs(c + t + c) cnt[c] += 2 cnt = Counter(s) mid = &#39;&#39; for c, v in cnt.items(): if v &amp; 1: if mid: return [] mid = c cnt[c] -= 1 ans = [] dfs(mid) return ans Java class Solution { private List&lt;String&gt; ans = new ArrayList&lt;&gt;(); private int[] cnt = new int[26]; private int n; public List&lt;String&gt; generatePalindromes(String s) { n = s.length(); for (char c : s.toCharArray()) { ++cnt[c - &#39;a&#39;]; } String mid = &#34;&#34;; for (int i = 0; i &lt; 26; ++i) { if (cnt[i] % 2 == 1) { if (!&#34;&#34;.equals(mid)) { return ans; } mid = String.valueOf((char) (i + &#39;a&#39;)); } } dfs(mid); return ans; } private void dfs(String t) { if (t.length() == n) { ans.add(t); return; } for (int i = 0; i &lt; 26; ++i) { if (cnt[i] &gt; 1) { String c = String.valueOf((char) (i + &#39;a&#39;)); cnt[i] -= 2; dfs(c + t + c); cnt[i] += 2; } } } } C++ class Solution { public: int n; vector&lt;string&gt; ans; unordered_map&lt;char, int&gt; cnt; vector&lt;string&gt; generatePalindromes(string s) { n = s.size(); for (char c : s) ++cnt[c]; string mid = &#34;&#34;; for (auto&amp; [k, v] : cnt) { if (v &amp; 1) { if (mid != &#34;&#34;) { return ans; } mid += k; } } dfs(mid); return ans; } void dfs(string t) { if (t.size() == n) { ans.push_back(t); return; } for (auto&amp; [k, v] : cnt) { if (v &gt; 1) { v -= 2; dfs(k + t + k); v += 2; } } } }; Go func generatePalindromes(s string) []string { cnt := map[byte]int{} for i := range s { cnt[s[i]]++ } mid := &#34;&#34; ans := []string{} for k, v := range cnt { if v%2 == 1 { if mid != &#34;&#34; { return ans } mid = string(k) } } var dfs func(t string) dfs = func(t string) { if len(t) == len(s) { ans = append(ans, t) return } for k, v := range cnt { if v &gt; 1 { cnt[k] -= 2 c := string(k) dfs(c + t + c) cnt[k] += 2 } } } dfs(mid) return ans }

 272. 最接近的二叉搜索树值 II 🔒 English Version
题目描述 给定二叉搜索树的根&nbsp;root&nbsp;、一个目标值&nbsp;target&nbsp;和一个整数&nbsp;k&nbsp;，返回BST中最接近目标的 k 个值。你可以按 任意顺序 返回答案。
题目&nbsp;保证&nbsp;该二叉搜索树中只会存在一种&nbsp;k 个值集合最接近&nbsp;target
&nbsp;
示例 1：
输入: root = [4,2,5,1,3]，目标值 = 3.714286，且 k = 2 输出: [4,3] 示例 2:
输入: root = [1], target = 0.000000, k = 1 输出: [1] &nbsp;
提示：
二叉树的节点总数为&nbsp;n 1 &lt;= k &lt;= n &lt;= 104 0 &lt;= Node.val &lt;= 109 -109&nbsp;&lt;= target &lt;= 109 &nbsp;
进阶：假设该二叉搜索树是平衡的，请问您是否能在小于&nbsp;O(n)（&nbsp;n = total nodes&nbsp;）的时间复杂度内解决该问题呢？
解法 方法一 Python3 # Definition for a binary tree node. # class TreeNode: # def __init__(self, val=0, left=None, right=None): # self.val = val # self.left = left # self.right = right class Solution: def closestKValues(self, root: TreeNode, target: float, k: int) -&gt; List[int]: def dfs(root): if root is None: return dfs(root.left) if len(q) &lt; k: q.append(root.val) else: if abs(root.val - target) &gt;= abs(q[0] - target): return q.popleft() q.append(root.val) dfs(root.right) q = deque() dfs(root) return list(q) Java /** * Definition for a binary tree node. * public class TreeNode { * int val; * TreeNode left; * TreeNode right; * TreeNode() {} * TreeNode(int val) { this.val = val; } * TreeNode(int val, TreeNode left, TreeNode right) { * this.val = val; * this.left = left; * this.right = right; * } * } */ class Solution { private List&lt;Integer&gt; ans; private double target; private int k; public List&lt;Integer&gt; closestKValues(TreeNode root, double target, int k) { ans = new LinkedList&lt;&gt;(); this.target = target; this.k = k; dfs(root); return ans; } private void dfs(TreeNode root) { if (root == null) { return; } dfs(root.left); if (ans.size() &lt; k) { ans.add(root.val); } else { if (Math.abs(root.val - target) &gt;= Math.abs(ans.get(0) - target)) { return; } ans.remove(0); ans.add(root.val); } dfs(root.right); } } C++ /** * Definition for a binary tree node. * struct TreeNode { * int val; * TreeNode *left; * TreeNode *right; * TreeNode() : val(0), left(nullptr), right(nullptr) {} * TreeNode(int x) : val(x), left(nullptr), right(nullptr) {} * TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {} * }; */ class Solution { public: queue&lt;int&gt; q; double target; int k; vector&lt;int&gt; closestKValues(TreeNode* root, double target, int k) { this-&gt;target = target; this-&gt;k = k; dfs(root); vector&lt;int&gt; ans; while (!q.empty()) { ans.push_back(q.front()); q.pop(); } return ans; } void dfs(TreeNode* root) { if (!root) return; dfs(root-&gt;left); if (q.size() &lt; k) q.push(root-&gt;val); else { if (abs(root-&gt;val - target) &gt;= abs(q.front() - target)) return; q.pop(); q.push(root-&gt;val); } dfs(root-&gt;right); } }; Go /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func closestKValues(root *TreeNode, target float64, k int) []int { var ans []int var dfs func(root *TreeNode) dfs = func(root *TreeNode) { if root == nil { return } dfs(root.Left) if len(ans) &lt; k { ans = append(ans, root.Val) } else { if math.Abs(float64(root.Val)-target) &gt;= math.Abs(float64(ans[0])-target) { return } ans = ans[1:] ans = append(ans, root.Val) } dfs(root.Right) } dfs(root) return ans }

