 if (!root) return; dfs(root-&gt;left); if (q.size() &lt; k) q.push(root-&gt;val); else { if (abs(root-&gt;val - target) &gt;= abs(q.front() - target)) return; q.pop(); q.push(root-&gt;val); } dfs(root-&gt;right); } }; Go /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func closestKValues(root *TreeNode, target float64, k int) []int { var ans []int var dfs func(root *TreeNode) dfs = func(root *TreeNode) { if root == nil { return } dfs(root.Left) if len(ans) &lt; k { ans = append(ans, root.Val) } else { if math.Abs(float64(root.Val)-target) &gt;= math.Abs(float64(ans[0])-target) { return } ans = ans[1:] ans = append(ans, root.Val) } dfs(root.Right) } dfs(root) return ans }

