1 &lt;= n &lt;= 104 Solutions Solution 1 Python3 class Solution: def numSquares(self, n: int) -&gt; int: m = int(sqrt(n)) f = [[inf] * (n + 1) for _ in range(m + 1)] f[0][0] = 0 for i in range(1, m + 1): for j in range(n + 1): f[i][j] = f[i - 1][j] if j &gt;= i * i: f[i][j] = min(f[i][j], f[i][j - i * i] + 1) return f[m][n] Java class Solution { public int numSquares(int n) { int m = (int) Math.sqrt(n); int[][] f = new int[m + 1][n + 1]; for (var g : f) { Arrays.fill(g, 1 &lt;&lt; 30); } f[0][0] = 0; for (int i = 1; i &lt;= m; ++i) { for (int j = 0; j &lt;= n; ++j) { f[i][j] = f[i - 1][j]; if (j &gt;= i * i) { f[i][j] = Math.min(f[i][j], f[i][j - i * i] + 1); } } } return f[m][n]; } } C++ class Solution { public: int numSquares(int n) { int m = sqrt(n); int f[m + 1][n + 1]; memset(f, 0x3f, sizeof(f)); f[0][0] = 0; for (int i = 1; i &lt;= m; ++i) { for (int j = 0; j &lt;= n; ++j) { f[i][j] = f[i - 1][j]; if (j &gt;= i * i) { f[i][j] = min(f[i][j], f[i][j - i * i] + 1); } } } return f[m][n]; } }; Go func numSquares(n int) int { m := int(math.Sqrt(float64(n))) f := make([][]int, m+1) const inf = 1 &lt;&lt; 30 for i := range f { f[i] = make([]int, n+1) for j := range f[i] { f[i][j] = inf } } f[0][0] = 0 for i := 1; i &lt;= m; i++ { for j := 0; j &lt;= n; j++ { f[i][j] = f[i-1][j] if j &gt;= i*i { f[i][j] = min(f[i][j], f[i][j-i*i]+1) } } } return f[m][n] } TypeScript function numSquares(n: number): number { const m = Math.floor(Math.sqrt(n)); const f: number[][] = Array(m + 1) .fill(0) .map(() =&gt; Array(n + 1).fill(1 &lt;&lt; 30)); f[0][0] = 0; for (let i = 1; i &lt;= m; ++i) { for (let j = 0; j &lt;= n; ++j) { f[i][j] = f[i - 1][j]; if (j &gt;= i * i) { f[i][j] = Math.min(f[i][j], f[i][j - i * i] + 1); } } } return f[m][n]; } Rust impl Solution { pub fn num_squares(n: i32) -&gt; i32 { let (row, col) = ((n as f32).sqrt().floor() as usize, n as usize); let mut dp = vec![vec![i32::MAX; col + 1]; row + 1]; dp[0][0] = 0; for i in 1..=row { for j in 0..=col { dp[i][j] = dp[i - 1][j]; if j &gt;= i * i { dp[i][j] = std::cmp::min(dp[i][j], dp[i][j - i * i] + 1); } } } dp[row][col] } } Solution 2 Python3 class Solution: def numSquares(self, n: int) -&gt; int: m = int(sqrt(n)) f = [0] + [inf] * n for i in range(1, m + 1): for j in range(i * i, n + 1): f[j] = min(f[j], f[j - i * i] + 1) return f[n] Java class Solution { public int numSquares(int n) { int m = (int) Math.sqrt(n); int[] f = new int[n + 1]; Arrays.fill(f, 1 &lt;&lt; 30); f[0] = 0; for (int i = 1; i &lt;= m; ++i) { for (int j = i * i; j &lt;= n; ++j) { f[j] = Math.min(f[j], f[j - i * i] + 1); } } return f[n]; } } C++ class Solution { public: int numSquares(int n) { int m = sqrt(n); int f[n + 1]; memset(f, 0x3f, sizeof(f)); f[0] = 0; for (int i = 1; i &lt;= m; ++i) { for (int j = i * i; j &lt;= n; ++j) { f[j] = min(f[j], f[j - i * i] + 1); } } return f[n]; } }; Go func numSquares(n int) int { m := int(math.Sqrt(float64(n))) f := make([]int, n+1) for i := range f { f[i] = 1 &lt;&lt; 30 } f[0] = 0 for i := 1; i &lt;= m; i++ { for j := i * i; j &lt;= n; j++ { f[j] = min(f[j], f[j-i*i]+1) } } return f[n] } TypeScript function numSquares(n: number): number { const m = Math.floor(Math.sqrt(n)); const f: number[] = Array(n + 1).fill(1 &lt;&lt; 30); f[0] = 0; for (let i = 1; i &lt;= m; ++i) { for (let j = i * i; j &lt;= n; ++j) { f[j] = Math.min(f[j], f[j - i * i] + 1); } } return f[n]; } Rust impl Solution { pub fn num_squares(n: i32) -&gt; i32 { let (row, col) = ((n as f32).sqrt().floor() as usize, n as usize); let mut dp = vec![i32::MAX; col + 1]; dp[0] = 0; for i in 1..=row { for j in i * i..=col { dp[j] = std::cmp::min(dp[j], dp[j - i * i] + 1); } } dp[col] } }

 280. 摆动排序 🔒 English Version
题目描述 给你一个的整数数组&nbsp;nums, 将该数组重新排序后使&nbsp;nums[0] &lt;= nums[1] &gt;= nums[2] &lt;= nums[3]...&nbsp;
输入数组总是有一个有效的答案。
&nbsp;
示例 1:
输入：nums = [3,5,2,1,6,4] 输出：[3,5,1,6,2,4] 解释：[1,6,2,5,3,4]也是有效的答案 示例 2:
输入：nums = [6,6,5,6,3,8] 输出：[6,6,5,6,3,8] &nbsp;
提示：
1 &lt;= nums.length &lt;= 5 * 104 0 &lt;= nums[i] &lt;= 104 输入的&nbsp;nums 保证至少有一个答案。
&nbsp;
进阶：你能在&nbsp;O(n)&nbsp;时间复杂度下解决这个问题吗？
解法 方法一 Python3 class Solution: def wiggleSort(self, nums: List[int]) -&gt; None: &#34;&#34;&#34; Do not return anything, modify nums in-place instead. &#34;&#34;&#34; for i in range(1, len(nums)): if (i % 2 == 1 and nums[i] &lt; nums[i - 1]) or ( i % 2 == 0 and nums[i] &gt; nums[i - 1] ): nums[i], nums[i - 1] = nums[i - 1], nums[i] Java class Solution { public void wiggleSort(int[] nums) { for (int i = 1; i &lt; nums.length; ++i) { if ((i % 2 == 1 &amp;&amp; nums[i] &lt; nums[i - 1]) || (i % 2 == 0 &amp;&amp; nums[i] &gt; nums[i - 1])) { swap(nums, i, i - 1); } } } private void swap(int[] nums, int i, int j) { int t = nums[i]; nums[i] = nums[j]; nums[j] = t; } } C++ class Solution { public: void wiggleSort(vector&lt;int&gt;&amp; nums) { for (int i = 1; i &lt; nums.size(); ++i) { if ((i % 2 == 1 &amp;&amp; nums[i] &lt; nums[i - 1]) || (i % 2 == 0 &amp;&amp; nums[i] &gt; nums[i - 1])) { swap(nums[i], nums[i - 1]); } } } }; Go func wiggleSort(nums []int) { for i := 1; i &lt; len(nums); i++ { if (i%2 == 1 &amp;&amp; nums[i] &lt; nums[i-1]) || (i%2 == 0 &amp;&amp; nums[i] &gt; nums[i-1]) { nums[i], nums[i-1] = nums[i-1], nums[i] } } }

